const HELP = {
it: {
  "name": ["Nome del progetto", "Ad esempio VPN Milano–Roma", "Serve solo a te: è il nome con cui ritrovi il progetto in «Apri» e nel file JSON esportato. Non finisce nella configurazione del FortiGate."],
  "fos": ["Versione FortiOS", "La versione installata sui FortiGate", "Scegli la versione che vedi sul FortiGate in alto a sinistra nella GUI o con «get system status». Alcuni comandi esistono solo da una certa versione: Fortissimo nasconde quelli che la tua versione non conosce, così non incolli righe che verrebbero rifiutate. Se i due FortiGate hanno versioni diverse, scegli la più vecchia."],
  "side.label": ["Nome del lato", "Ad esempio Milano o Cliente Rossi", "È solo un’etichetta per te: compare nello schema, nei commenti delle rotte e nel riepilogo. Non cambia il funzionamento della VPN.", true],
  "side.wan": ["Interfaccia WAN", "Ad esempio wan1", "È la porta del FortiGate collegata a Internet, dove arrivano e partono i pacchetti della VPN. Scrivi il nome esatto che vedi in Network → Interfaces (wan1, wan2, port1…). Se sbagli nome, la CLI rifiuta il tunnel."],
  "side.ip": ["IP pubblico", "Ad esempio 203.0.113.20", "È l’indirizzo Internet fisso di questo FortiGate: l’altro lato lo usa per sapere dove collegarsi. Lo trovi sull’interfaccia WAN o chiedendolo al fornitore della linea. Se l’IP cambia nel tempo, lascialo vuoto e compila l’FQDN dinamico.", true],
  "side.fqdn": ["FQDN dinamico", "Ad esempio sede.fortiddns.com", "Un nome DNS che punta sempre all’IP attuale del FortiGate, utile quando l’IP pubblico cambia. L’altro lato risolve il nome a ogni connessione. Compila questo oppure l’IP pubblico: almeno uno dei due serve. Per FortiClient è il nome che gli utenti vedono come gateway.", true],
  "side.nets": ["Reti locali", "Una per riga, ad esempio 192.168.10.0/24", "Sono le reti dietro questo FortiGate che l’altro lato deve poter raggiungere. Scrivile in formato CIDR (indirizzo/maschera). Dall’altra parte diventano rotte verso il tunnel; con i selettori per rete diventano anche le phase2. Le reti dei due lati non devono sovrapporsi."],
  "side.tunnel": ["Nome del tunnel", "Massimo 15 caratteri, ad esempio VPN_Milano", "È il nome della VPN su questo FortiGate e anche dell’interfaccia virtuale del tunnel, che poi userai nelle policy e nelle rotte. Usa lettere, numeri, trattino o trattino basso, senza spazi. Oltre 15 caratteri FortiOS lo rifiuta."],
  "side.tip": ["IP del tunnel", "Ad esempio 169.254.10.1", "Facoltativo con le rotte statiche, obbligatorio con il BGP. È un indirizzo assegnato all’interfaccia del tunnel: ti permette di fare ping da un FortiGate all’altro attraverso la VPN e di far parlare il BGP. Usa una piccola rete dedicata che non esiste in nessuna LAN, ad esempio 169.254.10.0/30, con un IP per lato.", true],
  "tunPrefix": ["Maschera della rete del tunnel", "/30 nella maggior parte dei casi", "Indica quanto è grande la rete che contiene i due IP del tunnel. /30 va bene sempre; /31 usa solo due indirizzi ma qualche apparato vecchio non lo gestisce. Se non hai compilato gli IP del tunnel, questo campo non ha effetto."],
  "auth.method": ["Metodo", "PSK nella maggior parte dei casi", "È il modo in cui i due FortiGate si riconoscono. Con la PSK scrivi la stessa password lunga su entrambi: semplice. Con i certificati ogni FortiGate ha un certificato firmato da una CA: più sicuro, ma devi prima creare e importare i certificati."],
  "psk": ["Chiave pre-condivisa (PSK)", "Premi Genera per una chiave sicura", "È la password segreta che i due lati devono avere identica, carattere per carattere. Usa Genera: crea 32 caratteri casuali. Fortissimo non la salva e non la esporta, quindi copiala in un posto sicuro prima di chiudere la pagina. Se resta vuota, nella CLI trovi <PSK> da sostituire."],
  "auth.cert": ["Certificato locale", "Nome del certificato già importato sul FortiGate", "È il certificato con cui questo FortiGate dimostra chi è. Deve già esistere in System → Certificates: scrivi esattamente il nome che vedi lì."],
  "auth.peer": ["Utente peer PKI", "Ad esempio PEER_ROMA", "È un oggetto che Fortissimo crea per dire al FortiGate quale certificato accettare dall’altro lato: contiene la CA ed eventualmente il nome del certificato. Scegli un nome a piacere."],
  "auth.ca": ["CA del peer", "Nome della CA già importata", "È l’autorità che ha firmato il certificato dell’altro lato. Il suo certificato deve essere importato su questo FortiGate (System → Certificates, sezione CA). Senza, il tunnel non si autentica."],
  "auth.cn": ["Common Name del peer", "Ad esempio fgt-roma.azienda.it", "Se lo compili, il FortiGate accetta solo il certificato con questo nome. Se lo lasci vuoto accetta qualsiasi certificato firmato dalla CA indicata: comodo, ma meno restrittivo.", true],
  "ident.networkId": ["Network ID", "0 se c’è un solo tunnel dial-up IKEv2", "Serve solo quando sulla stessa WAN ci sono più tunnel dial-up IKEv2 (ad esempio uno per i dipendenti e uno per i consulenti). Il client invia questo numero e il FortiGate sceglie il tunnel con lo stesso numero. Senza, tutti finiscono nel primo tunnel e ottieni errori di credenziali. 0 = disattivato; ogni tunnel deve avere un numero diverso, da 1 a 255."],
  "ident.usedIds": ["Network ID già in uso", "Ad esempio 0, 1", "Scrivi i Network ID degli altri tunnel dial-up IKEv2 già presenti sulla stessa WAN, separati da virgola. Non finisce nella configurazione: serve solo alle verifiche per avvisarti se scegli un numero già occupato. I tunnel senza Network ID contano come 0.", true],
  "ident.localid": ["Local ID della filiale", "Ad esempio filiale-roma", "È un nome con cui la filiale si presenta all’hub. Serve se sull’hub vuoi accettare solo questa filiale (Peer accettati = solo l’ID indicato) o se hai più filiali da distinguere. Se lo lasci vuoto la filiale si presenta con il suo IP.", true],
  "ident.peerMode": ["Peer accettati dall’hub", "Solo l’ID indicato è più sicuro", "Con «qualsiasi» l’hub accetta chiunque conosca la PSK. Con «solo il peer ID indicato» accetta solo la filiale che si presenta con quel Local ID: un altro dispositivo con la stessa PSK resta fuori."],
  "crypto.ike": ["Versione IKE", "IKEv2", "IKE è il protocollo che negozia la VPN. Usa IKEv2: è più moderno, più veloce e più robusto. IKEv1 serve solo con apparati vecchi che non conoscono IKEv2; FortiClient non lo supporta più dalla 7.4.4."],
  "crypto.mode": ["Modalità IKEv1", "Main", "Esiste solo con IKEv1. Main è la scelta sicura. Aggressive invia l’identità in chiaro e permette di attaccare la PSK offline: usala solo se un peer vecchio la richiede davvero."],
  "crypto.p1": ["Proposte phase1", "Ad esempio aes256-sha256", "Sono gli algoritmi che proteggono la «stretta di mano» iniziale tra i due lati. Basta che almeno una proposta sia uguale sui due lati; Fortissimo usa le stesse su entrambi. Le voci GCM e ChaCha20 funzionano solo con IKEv2."],
  "crypto.dh1": ["Gruppi Diffie-Hellman phase1", "20 (consigliato) o 21", "Il gruppo DH decide quanto è robusto lo scambio della chiave. 20 o 21 sono moderni e sicuri; sotto il 14 sono deboli. Meglio un solo gruppo uguale sui due lati: se ne metti più di uno, il primo tentativo può fallire e la negoziazione richiede un giro in più."],
  "crypto.life1": ["Durata phase1 (secondi)", "86400, cioè 24 ore", "Ogni quanto i due lati rinnovano le chiavi della phase1. Il valore normale è 86400 secondi (un giorno). Non serve cambiarlo; se lo cambi, mettilo uguale sui due lati."],
  "crypto.p2": ["Proposte phase2", "Ad esempio aes256gcm", "Sono gli algoritmi che cifrano il traffico vero e proprio. aes256gcm è il più efficiente sui FortiGate recenti perché cifra e controlla l’integrità in un colpo solo. Basta una proposta in comune tra i lati."],
  "crypto.pfs": ["Perfect Forward Secrecy", "Attivo", "Con PFS ogni rinnovo delle chiavi del traffico ne crea di completamente nuove: se un giorno una chiave venisse rubata, il traffico passato resterebbe protetto. Lascialo attivo; va attivato o disattivato su entrambi i lati allo stesso modo."],
  "crypto.dh2": ["Gruppi DH phase2", "Gli stessi della phase1", "Contano solo se la PFS è attiva. Mettili uguali alla phase1 e uguali sui due lati."],
  "crypto.life2": ["Durata phase2 (secondi)", "43200, cioè 12 ore", "Ogni quanto si rinnovano le chiavi che cifrano il traffico. 43200 secondi (12 ore) è il valore normale di FortiOS. Mettilo uguale sui due lati."],
  "sel.mode": ["Selettori", "Tutto il traffico (0.0.0.0/0)", "I selettori dicono quali reti possono passare nella VPN. Tra due FortiGate scegli «tutto il traffico»: è il più semplice, poi decidono rotte e policy cosa passa davvero. Scegli «una phase2 per coppia di reti» solo se l’altro lato è un apparato che lo richiede, oppure se vuoi limitare le reti già a livello di VPN."],
  "route.on": ["Rotte statiche", "Attivo", "Le rotte dicono al FortiGate che per raggiungere le reti dell’altro lato deve usare il tunnel. Senza rotte la VPN può essere su ma il traffico non ci entra. Disattivalo solo se le rotte le gestisci in altro modo, ad esempio con SD-WAN."],
  "route.distance": ["Distanza amministrativa", "10", "Se esistono più strade verso la stessa rete, il FortiGate sceglie quella con la distanza più bassa. 10 è il valore normale. Alzalo solo se un altro percorso deve avere la precedenza sulla VPN."],
  "route.bh": ["Rotte blackhole", "Attivo", "Se il tunnel cade, la rotta verso la VPN sparisce e il traffico per l’altra sede potrebbe uscire su Internet senza cifratura. La blackhole è una rotta di riserva che in quel caso butta via i pacchetti. Lasciala attiva."],
  "route.bhDistance": ["Distanza blackhole", "254", "Deve essere più alta della distanza delle rotte della VPN: così la blackhole si attiva solo quando il tunnel è giù. 254 va bene quasi sempre."],
  "dial.auth": ["Utenti", "Dove vengono controllate le credenziali", "Locali: utenti creati sul FortiGate, ideale per pochi utenti, con FortiToken. LDAP: utenti di Active Directory. RADIUS: un server come NPS controlla le credenziali (anche con MFA). SAML Entra ID: login Microsoft 365 con la sua MFA, ma richiede più passaggi in Entra."],
  "dial.group": ["Gruppo utenti FortiGate", "Ad esempio VPN_USERS", "Nome del gruppo che Fortissimo crea sul FortiGate: solo i membri possono collegarsi a questa VPN. Scegli un nome a piacere; se esiste già, viene aggiornato."],
  "dial.users": ["Utenti locali del gruppo", "Ad esempio mario.rossi, anna.bianchi", "Nomi degli utenti locali da mettere nel gruppo, separati da virgola. Gli utenti devono già esistere in User & Authentication → User Definition, con password e possibilmente FortiToken: Fortissimo non li crea."],
  "dial.ldapServer": ["Server LDAP", "Ad esempio AD_LDAP", "Nome dell’oggetto server LDAP sul FortiGate. Se attivi «Crea anche il server LDAP» Fortissimo lo crea con questo nome; altrimenti deve già esistere in User & Authentication → LDAP Servers."],
  "dial.ldapDN": ["DN del gruppo AD", "CN=VPN,OU=Gruppi,DC=azienda,DC=local", "È il «percorso completo» del gruppo di Active Directory autorizzato alla VPN. Lo trovi in Utenti e computer di AD: attiva Visualizza → Funzionalità avanzate, apri il gruppo → Editor attributi → distinguishedName, e copialo identico."],
  "dial.radiusServer": ["Server RADIUS", "Ad esempio NPS", "Nome dell’oggetto server RADIUS sul FortiGate. Se attivi «Crea anche il server RADIUS» Fortissimo lo crea con questo nome; altrimenti deve già esistere in User & Authentication → RADIUS Servers."],
  "dial.samlServer": ["Nome del server SAML", "Ad esempio entra-vpn", "Nome dell’oggetto che collega il FortiGate a Entra ID. Scegli un nome a piacere, senza spazi."],
  "dial.samlPort": ["Porta SAML", "Ad esempio 9443", "È la porta su cui FortiClient apre il login Microsoft prima di creare il tunnel. Deve essere libera: non usare la porta HTTPS di amministrazione del FortiGate né quella dell’SSL-VPN. La stessa porta va indicata in FortiClient (è già nel file generato)."],
  "dial.tenant": ["ID tenant Entra", "Un codice tipo e559b5c4-…", "È l’identificativo della tua organizzazione Microsoft. Lo trovi in Entra admin center → Panoramica → ID tenant. Fortissimo lo usa per comporre gli indirizzi di login di Microsoft."],
  "dial.groupId": ["ID oggetto del gruppo Entra", "Un codice tipo aa4932cf-…", "È l’ID del gruppo di Entra i cui membri possono usare la VPN. Lo trovi in Entra → Gruppi → il gruppo → ID oggetto. Il FortiGate lascia entrare solo chi ha questo ID tra i propri gruppi."],
  "dial.idpCert": ["Certificato IdP", "Ad esempio REMOTE_Cert_1", "È il certificato di Entra che hai scaricato (Base64) e importato sul FortiGate come Remote Certificate. Scrivi il nome che il FortiGate gli ha dato. Serve a verificare che le risposte di login arrivino davvero da Microsoft."],
  "dial.spCert": ["Certificato SP", "Fortinet_Factory per il primo test", "È il certificato che il FortiGate presenta durante il login SAML. Per provare va bene Fortinet_Factory (FortiClient mostrerà un avviso); in produzione usa un certificato valido per l’FQDN, ad esempio Let’s Encrypt."],
  "dial.authCert": ["Certificato di autenticazione", "Ad esempio le-vpn", "Se lo compili, Fortissimo imposta auth-cert, il certificato che FortiClient vede sulla porta SAML: con un certificato valido sparisce l’avviso di sicurezza. Attenzione: è un’impostazione globale del FortiGate, controlla prima che non serva ad altro. Se lo lasci vuoto, non viene toccato.", true],
  "dial.poolStart": ["Pool: primo IP", "Ad esempio 10.254.10.10", "I client collegati ricevono un indirizzo da questo intervallo. Usa una rete dedicata alla VPN che non esista in nessuna LAN, altrimenti avrai conflitti di indirizzi."],
  "dial.poolEnd": ["Pool: ultimo IP", "Ad esempio 10.254.10.210", "Ultimo indirizzo dell’intervallo. Il numero di indirizzi tra primo e ultimo è il numero massimo di client collegati insieme."],
  "dial.dns1": ["DNS 1", "Ad esempio il domain controller", "Il server DNS che i client usano quando sono in VPN, di solito il DNS interno o il domain controller. Senza, i client non risolvono i nomi dei server interni.", true],
  "dial.dns2": ["DNS 2", "Secondo DNS interno", "Server DNS di riserva, usato se il primo non risponde.", true],
  "dial.split": ["Instradamento", "Split tunnel nella maggior parte dei casi", "Split tunnel: in VPN passa solo il traffico verso le reti dell’azienda, mentre Internet esce dalla connessione di casa. Tunnel completo: anche la navigazione passa dal FortiGate, più controllabile ma più lento e serve una policy verso Internet."],
  "dial.client": ["Nome della connessione", "Ad esempio Azienda VPN", "È il nome che l’utente vede nell’elenco delle VPN di FortiClient. Scegli qualcosa di chiaro."],
  "dial.authTimeout": ["Tempo per l’MFA (secondi)", "Ad esempio 60", "È quanto il FortiGate aspetta la verifica delle credenziali. Il valore di fabbrica è solo 5 secondi: troppo poco per leggere un codice FortiToken o approvare una notifica, e il login fallisce. 60 è un buon valore; il massimo è 300. È un’impostazione globale (remoteauthtimeout). Se lo lasci vuoto non viene toccata.", true],
  "dial.saveUser": ["Ricorda il nome utente", "In FortiClient", "Se attivo, FortiClient ricorda il nome utente tra una connessione e l’altra. La password non viene salvata. Disattivalo su PC condivisi."],
  "dial.ldapCreate": ["Crea anche il server LDAP", "Disattiva se esiste già", "Se attivo, Fortissimo genera anche il collegamento del FortiGate al domain controller (config user ldap). Se il server LDAP esiste già sul FortiGate, disattivalo e scrivi solo il suo nome."],
  "dial.ldapIp": ["Indirizzo del domain controller", "Ad esempio 192.168.10.10", "IP o nome del domain controller che il FortiGate interroga. Il FortiGate deve poterlo raggiungere sulla porta 389 (o 636 con LDAPS)."],
  "dial.ldapCnid": ["Attributo del nome utente", "sAMAccountName", "Indica come l’utente scrive il proprio nome al login. sAMAccountName: il nome breve (mario.rossi). userPrincipalName: l’indirizzo completo (mario.rossi@azienda.it). Il valore di fabbrica del FortiGate, cn, non funziona con i nomi di accesso di Active Directory."],
  "dial.ldapBase": ["DN base", "Ad esempio DC=azienda,DC=local", "È da dove il FortiGate inizia a cercare gli utenti. Metti la radice del dominio: se il dominio è azienda.local scrivi DC=azienda,DC=local. Così trova gli utenti in qualsiasi cartella (OU)."],
  "dial.ldapBind": ["DN dell’account di bind", "CN=svc-fortigate,OU=Servizi,DC=azienda,DC=local", "È l’account di servizio con cui il FortiGate entra in Active Directory per cercare gli utenti. Serve il percorso completo (distinguishedName), non il solo nome: lo copi dall’Editor attributi dell’utente. Crea un utente dedicato, senza privilegi e con password che non scade."],
  "ldapPwd": ["Password dell’account di bind", "La password dell’account di servizio", "Deve essere identica a quella dell’account in Active Directory. Fortissimo non la salva e non la esporta; se la lasci vuota, nella CLI trovi un segnaposto da sostituire.", true],
  "dial.ldapSecure": ["Connessione sicura", "LDAPS se il DC ha un certificato", "Nessuna: la password dell’account di servizio viaggia in chiaro sulla rete interna. LDAPS: tutto cifrato sulla porta 636, ma il domain controller deve avere un certificato e la sua CA va importata sul FortiGate. STARTTLS: come LDAPS ma sulla porta 389."],
  "dial.ldapNested": ["Gruppi annidati", "Solo se usi gruppi dentro gruppi", "Attivalo se gli utenti non sono direttamente nel gruppo VPN ma in un altro gruppo che ne fa parte. Se gli utenti sono membri diretti, lascialo spento."],
  "dial.radiusCreate": ["Crea anche il server RADIUS", "Disattiva se esiste già", "Se attivo, Fortissimo genera anche il collegamento del FortiGate al server RADIUS (config user radius). Se esiste già sul FortiGate, disattivalo e scrivi solo il suo nome."],
  "dial.radiusIp": ["Indirizzo del server RADIUS", "Ad esempio 192.168.10.20", "IP o nome del server RADIUS (ad esempio NPS). Il FortiGate deve poterlo raggiungere sulla porta UDP 1812."],
  "radiusPwd": ["Segreto condiviso", "Uguale al client RADIUS su NPS", "È la password che FortiGate e server RADIUS usano tra loro. Deve essere identica a quella impostata sul server per il client FortiGate. Fortissimo non la salva; se vuota, nella CLI resta un segnaposto.", true],
  "dial.radiusTimeout": ["Timeout del server (secondi)", "Ad esempio 60 se c’è MFA", "Quanto il FortiGate aspetta la risposta del server RADIUS. Il valore di fabbrica è di pochi secondi: se il server chiede anche un secondo fattore (app o SMS), alzalo, altrimenti il login scade prima che l’utente risponda. Se lo lasci vuoto resta il valore di fabbrica.", true],
  "bgp.on": ["Usa il BGP", "Spento se hai poche reti", "Il BGP è un modo automatico di scambiarsi le reti: ogni lato annuncia le sue e il FortiGate si accorge subito se il tunnel cade. Conviene con molte reti, due linee Internet o molte filiali. Per due sedi con poche reti le rotte statiche sono più semplici."],
  "bgp.asA": ["AS del lato A", "Ad esempio 65001", "Un numero che identifica il lato A per il BGP. Usa numeri privati da 64512 a 65534. Con numeri diversi sui due lati (consigliato) la sessione è eBGP; con lo stesso numero è iBGP."],
  "bgp.asB": ["AS del lato B", "Ad esempio 65002", "Il numero BGP del lato B. Di solito diverso dal lato A."],
  "bgp.ridA": ["Router ID del lato A", "Ad esempio 10.0.0.1", "Un identificativo in formato indirizzo IP, unico per ogni FortiGate. Se lo lasci vuoto il FortiGate ne sceglie uno da solo; fissarlo evita che cambi quando cambiano le interfacce.", true],
  "bgp.ridB": ["Router ID del lato B", "Ad esempio 10.0.0.2", "Come per il lato A: facoltativo, ma deve essere diverso da quello del lato A.", true],
  "bgp.overlay": ["Rete overlay", "Ad esempio 169.254.20.0/24", "È una piccola rete usata solo per gli IP dei tunnel di hub e filiali, non per i PC. L’hub accetta il BGP da tutti gli indirizzi di questa rete. L’ultimo indirizzo resta riservato e non va assegnato a nessuno."],
  "bgp.tipHub": ["IP del tunnel dell’hub", "Ad esempio 169.254.20.1", "Indirizzo dell’hub dentro la rete overlay. Le filiali lo usano per parlare BGP con l’hub."],
  "bgp.tipBranch": ["IP del tunnel della filiale", "Ad esempio 169.254.20.2", "Indirizzo di questa filiale dentro la rete overlay. Ogni filiale deve averne uno diverso."],
  "bgp.keepalive": ["Keepalive (secondi)", "Vuoto = 60", "Ogni quanti secondi i due lati si scambiano un segnale di vita. Valori bassi (ad esempio 10) fanno accorgere prima dei guasti. Se lo lasci vuoto resta il valore di FortiOS.", true],
  "bgp.holdtime": ["Holdtime (secondi)", "Vuoto = 180", "Dopo quanti secondi senza segnali il vicino è considerato caduto. Deve essere almeno il triplo del keepalive. Se lo lasci vuoto resta il valore di FortiOS.", true],
  "bgp.soft": ["Soft reconfiguration", "Attivo", "Il FortiGate conserva una copia delle rotte ricevute: se cambi un filtro non deve far cadere e rialzare la sessione. Costa un po’ di memoria; lascialo attivo."],
  "bgp.ldf": ["Link-down failover", "Attivo", "Se l’interfaccia del tunnel va giù, la sessione BGP viene chiusa subito invece di aspettare l’holdtime: le rotte di riserva entrano in gioco in pochi istanti."],
  "bgp.gr": ["Graceful restart", "Spento salvo cluster", "Mantiene le rotte mentre il processo BGP si riavvia o il cluster passa all’altro FortiGate. Utile con FortiGate in HA; altrimenti lascialo spento."],
  "bgpPwd": ["Password BGP", "Uguale sui due lati", "Protegge la sessione BGP da vicini non autorizzati. Deve essere identica sui due lati. Non viene salvata né esportata.", true],
  "dual.on": ["Secondo tunnel su un’altra linea", "Solo se hai due linee Internet", "Crea un secondo tunnel che passa dalla seconda linea Internet del lato A: se la prima linea cade, la VPN continua sulla seconda. Il lato B può avere una o due linee."],
  "dual.aWan": ["Interfaccia della seconda linea", "Ad esempio wan2", "La porta del FortiGate A collegata alla seconda linea Internet."],
  "dual.aIp": ["IP pubblico della seconda linea", "Ad esempio 198.51.100.50", "L’indirizzo Internet della seconda linea del lato A: il lato B lo usa per costruire il secondo tunnel. Serve questo oppure l’FQDN.", true],
  "dual.aFqdn": ["FQDN della seconda linea", "Se l’IP non è fisso", "Nome DNS che punta all’IP della seconda linea, se questa ha un IP che cambia. Serve questo oppure l’IP.", true],
  "dual.aTunnel": ["Nome del secondo tunnel", "Ad esempio VPN2_to_B", "Nome del secondo tunnel sul lato A. Massimo 15 caratteri, diverso dal primo."],
  "dual.aTip": ["IP del secondo tunnel", "Ad esempio 169.254.10.5", "Indirizzo sull’interfaccia del secondo tunnel. Facoltativo con le rotte statiche, obbligatorio con il BGP. Usa una rete diversa da quella del primo tunnel.", true],
  "dual.bWan": ["Interfaccia della seconda linea", "Solo se il lato B ha due linee", "Se anche il lato B ha una seconda linea, scrivi qui la sua porta. Se il lato B ha una sola linea lascia vuoto: il secondo tunnel arriverà sulla sua unica WAN.", true],
  "dual.bIp": ["IP pubblico della seconda linea", "Solo se il lato B ha due linee", "L’indirizzo Internet della seconda linea del lato B. Lascia vuoto se il lato B ha una sola linea.", true],
  "dual.bFqdn": ["FQDN della seconda linea", "Se l’IP non è fisso", "Nome DNS della seconda linea del lato B, se l’IP cambia.", true],
  "dual.bTunnel": ["Nome del secondo tunnel", "Ad esempio VPN2_to_A", "Nome del secondo tunnel sul lato B. Massimo 15 caratteri, diverso dal primo."],
  "dual.bTip": ["IP del secondo tunnel", "Ad esempio 169.254.10.6", "Facoltativo con le rotte statiche, obbligatorio con il BGP. Deve stare nella stessa piccola rete dell’IP del secondo tunnel del lato A.", true],
  "dual.mode": ["Uso del secondo tunnel", "Di riserva nella maggior parte dei casi", "Di riserva: i due tunnel restano accesi, tutto passa dal primo e il secondo prende il traffico se il primo cade. In standby: il secondo tunnel resta spento e si accende solo quando il primo cade (opzione monitor); consuma meno ma il passaggio è un po’ più lento. In parallelo: il traffico si divide sui due, utile se le linee sono simili e vuoi sommarne la banda."],
  "dual.backupDist": ["Distanza del tunnel di riserva", "Ad esempio 20", "Deve essere più alta della distanza delle rotte principali (di solito 10) e più bassa di quella delle blackhole (254). Così il secondo tunnel si usa solo quando il primo è giù."],
  "trans.mode": ["Protocollo IKE", "UDP", "Normalmente la VPN usa UDP sulle porte 500 e 4500. Alcune reti (alberghi, reti ospiti, aziende) le bloccano: con TCP la VPN passa lo stesso, ma va un po’ più piano. La modalità automatica, che prova UDP e poi TCP, esiste solo da FortiOS 7.6."],
  "trans.port": ["Porta TCP", "Ad esempio 10443", "La porta TCP su cui il FortiGate riceve la VPN in TCP. È un’impostazione globale: cambiarla fa cadere tutti i tunnel IPsec per qualche istante. Non può coincidere con la porta HTTPS di amministrazione o con un VIP."],
  "trans.threshold": ["Soglia di fallback (secondi)", "Vuoto = valore di FortiOS", "Dopo quanti secondi senza risposta in UDP il client prova TCP. Da 1 a 300.", true],
  "dial.exclude": ["Reti da tenere fuori dal tunnel", "Una per riga, ad esempio 192.168.1.0/24", "Con il tunnel completo tutto passa dal FortiGate. Qui scrivi le reti che devono restare fuori, cioè raggiungibili direttamente da casa dell’utente: ad esempio un servizio cloud che non deve passare dalla sede. Se lo lasci vuoto, passa tutto.", true],
  "dial.localLan": ["Lascia raggiungere la rete di casa", "Stampante, NAS, TV dell’utente", "Con il tunnel completo l’utente perde l’accesso ai dispositivi della propria rete di casa. Attivandolo, FortiClient lascia raggiungere la LAN locale. Viene impostato nel file FortiClient."],
  "dial.domains": ["Domini interni (split DNS)", "Ad esempio azienda.local", "I nomi che finiscono con questi domini vengono risolti dal DNS della VPN; tutti gli altri dal DNS di casa dell’utente. Così la navigazione non rallenta e i server interni si trovano. Separali con spazio o virgola. Disponibile da FortiOS 7.4.1. Se lo lasci vuoto, il DNS della VPN risolve tutto.", true],
  "dial.suffix": ["Suffissi DNS", "Ad esempio azienda.local", "Il client aggiunge questi suffissi ai nomi brevi: scrivendo «server01» trova «server01.azienda.local». Disponibile da FortiOS 7.6.4.", true],
  "gwm.mode": ["Accetta connessioni da", "Ovunque, salvo esigenze di sicurezza", "Restringe chi può anche solo iniziare la negoziazione. «Da una rete» o «da un intervallo» se i client o le filiali hanno IP noti; «da un paese» per bloccare tentativi dall’estero. Richiede FortiOS 7.4.4. Attenzione: chi resta fuori non riesce a collegarsi anche con le credenziali giuste."],
  "gwm.subnet": ["Rete ammessa", "Ad esempio 203.0.113.0/24", "Solo gli indirizzi Internet dentro questa rete possono collegarsi. Formato CIDR."],
  "gwm.start": ["Primo IP ammesso", "Ad esempio 203.0.113.10", "Primo indirizzo Internet dell’intervallo da cui accettare connessioni."],
  "gwm.end": ["Ultimo IP ammesso", "Ad esempio 203.0.113.50", "Ultimo indirizzo dell’intervallo."],
  "gwm.country": ["Paese ammesso", "Codice di due lettere, ad esempio IT", "Solo gli indirizzi che il database GeoIP di FortiGuard assegna a questo paese possono collegarsi. Chi è all’estero, o usa una rete mobile con uscita all’estero, resta fuori."],
  "dual.holdType": ["Ritorno al tunnel principale", "Subito nella maggior parte dei casi", "Quando la linea principale torna, il FortiGate rientra sul primo tunnel. «Subito» lo fa appena possibile; «dopo un ritardo» aspetta qualche secondo, utile se la linea principale va e viene."],
  "dual.holdDelay": ["Ritardo (secondi)", "Ad esempio 60", "Quanti secondi di linea principale stabile prima di tornarci sopra."],
  "fec.on": ["Correzione degli errori (FEC)", "Solo su linee che perdono pacchetti", "Per ogni gruppo di pacchetti il FortiGate ne invia alcuni di correzione: se un pacchetto si perde, l’altro lato lo ricostruisce senza ritrasmissione. Utile su 4G, satellite o radio, per voce e video. Costa più banda e disattiva l’accelerazione hardware del tunnel. Viene attivato su entrambi i lati."],
  "fec.base": ["Pacchetti base", "Vuoto = 20", "Ogni quanti pacchetti normali inviare il gruppo di correzione. Da 1 a 40.", true],
  "fec.redundant": ["Pacchetti di correzione", "Vuoto = 10", "Quanti pacchetti di correzione per ogni gruppo. Più sono, più perdite si recuperano e più banda si usa: con 20 base e 10 di correzione il traffico cresce di circa il 50%. Da 1 a 20.", true],
  "bx.autoLink": ["Quando aggiungi un nodo", "All’hub nella maggior parte dei casi", "All’hub: il nuovo nodo riceve una sessione e un tunnel IPsec verso il route reflector. A tutti: una sessione e un tunnel verso ogni FortiGate già presente (full mesh, N·(N−1)/2 tunnel). A mano: il nodo nasce senza sessioni. Tunnel e sessioni restano modificabili uno per uno."],
  "bx.pool": ["Rete per gli IP dei tunnel", "Ad esempio 169.254.100.0/24", "Da questa rete Fortissimo prende una /30 per ogni tunnel generato tra FortiGate con IP pubblico. Usa una rete che non esista in nessuna LAN. Gli IP restano modificabili nella sessione."],
  "bn.wan": ["Interfaccia WAN", "Ad esempio wan1", "La porta del FortiGate verso Internet su cui nascono i tunnel IPsec generati. Ogni tunnel può usarne un’altra."],
  "bn.pubIp": ["IP pubblico", "Ad esempio 203.0.113.20", "L’indirizzo a cui gli altri FortiGate si collegano. Se l’IP cambia usa l’FQDN, oppure segna il nodo come IP dinamico.", true],
  "bn.fqdn": ["FQDN", "Ad esempio sede.fortiddns.com", "Nome DNS del FortiGate quando l’IP pubblico cambia: gli altri lati usano remotegw-ddns.", true],
  "bn.dyn": ["IP dinamico o dietro NAT", "Nessuno può chiamare questo FortiGate", "Il nodo chiama gli altri ma non può essere chiamato. Verso un nodo con IP pubblico il tunnel diventa dial-up: l’altro lato fa da hub con un tunnel condiviso e accetta il BGP con neighbor-range."],
  "bn.dialName": ["Nome del tunnel dial-up", "Ad esempio DIAL_BGP", "Il tunnel condiviso con cui questo FortiGate accetta tutti gli spoke a IP dinamico. Massimo 15 caratteri."],
  "bn.overlay": ["Rete degli spoke dinamici", "Ad esempio 169.254.200.0/24", "Rete da cui prendono l’IP del tunnel l’hub e gli spoke dinamici. L’hub accetta il BGP da tutta questa rete; l’ultimo indirizzo resta riservato."],
  "bn.dialIp": ["IP dell’hub nella rete degli spoke", "Ad esempio 169.254.200.1", "L’indirizzo del tunnel dial-up su questo FortiGate: gli spoke lo usano come vicino BGP."],
  "bl.ipsec": ["Genera il tunnel IPsec", "Attivo per i FortiGate collegati via Internet", "Fortissimo crea phase1, phase2 e IP del tunnel su entrambi i nodi, con la crittografia della sezione IPsec e la PSK unica. Spegnilo se il tunnel esiste già."],
  "bl.tname": ["Nome del tunnel", "Massimo 15 caratteri", "Nome della phase1 e dell’interfaccia del tunnel su questo FortiGate. Proposto in automatico, puoi cambiarlo."],
  "bl.twan": ["WAN del tunnel", "Vuoto = la linea del tunnel, in grigio", "Interfaccia da cui parte questo tunnel. Cambiala per far passare un secondo tunnel su un’altra linea."],
  "bl.tgw": ["Gateway remoto", "Vuoto = l’indirizzo della linea dell’altra sede, in grigio", "L’indirizzo a cui questo FortiGate si collega. Cambialo quando l’altro nodo ha più linee e questo tunnel deve usarne un’altra.", true],
  "bl.tip": ["IP del tunnel", "Assegnato in automatico", "Indirizzo dell’interfaccia del tunnel su questo FortiGate: l’altro lato lo usa come vicino BGP. I due IP stanno nella stessa /30."],
  "bl.cOwn": ["Crittografia dedicata", "Spento = quella della sezione IPsec", "Attivalo se questo tunnel deve usare proposte o gruppi DH diversi, ad esempio verso un apparato più vecchio. Parte da una copia della crittografia della sezione IPsec."],
  "bx.multipath": ["Multipath", "Con più sessioni verso la stessa sede", "Con più sessioni verso la stessa sede il FortiGate usa insieme tutti i percorsi equivalenti invece di uno solo (ibgp-multipath ed ebgp-multipath). Utile con due tunnel in parallelo; spento se un percorso deve fare solo da riserva."],
  "bn.name": ["Nome", "Ad esempio Milano o Provider", "Serve a riconoscere il nodo nello schema, nella descrizione dei vicini (set description) e nel nome della scheda. Per un lato del tunnel IPsec, vuoto usa il nome di quel lato.", true],
  "bn.as": ["AS", "Ad esempio 65001", "Il numero BGP del nodo. Stesso AS tra due nodi = sessione iBGP, AS diversi = eBGP. Tra le tue sedi usa AS privati (64512–65534); verso un provider usa l’AS concordato con lui."],
  "ms.sdwan": ["Più linee per sede", "Facoltativo", "Ogni sede può avere fino a 8 linee (fibra, FWA, LTE, Starlink, linee private come MPLS, ponti radio o satellite). Fortissimo crea un tunnel per ogni coppia di linee tra due sedi e li raggruppa: in una zona SD-WAN, con health-check e regole che scelgono il tunnel migliore, oppure in un aggregato IPsec per ogni coppia di sedi, che li usa tutti insieme.", true],
  "ms.col.lan": ["Interfaccia LAN", "Ad esempio lan, internal o una VLAN", "L’interfaccia del FortiGate dove sta la rete interna della sede. Le firewall policy generate vanno da qui alla zona SD-WAN e ritorno."],
  "ms.col.type": ["Tipo di linea", "Cavo, satellite, LTE/5G o privata", "Il tipo dà la lettera della linea nei nomi a codici (W cavo o fibra, S satellite, L LTE) e serve a escludere da solo le coppie impossibili. Una linea privata (MPLS, ponte radio, link satellitare dedicato) raggiunge solo le linee private della stessa rete: scrivi il nome della rete nel campo che compare, uguale su tutte le sedi che la condividono (ad esempio MPLS1, oppure SAT-MIL per un link dedicato tra due sedi). Come indirizzo usa l’IP della sede su quella rete. Cavo, satellite e LTE si raggiungono tra loro via Internet; con il costo decidi quanto usarle."],
  "ms.col.cost": ["Costo", "0 per la linea principale, di più per le altre", "Il costo di un tunnel è la somma dei costi delle sue due linee. Tra i tunnel che rispettano le soglie SLA il FortiGate usa quello che costa meno: dai un costo alto alle linee a consumo come LTE."],
  "ms.zone": ["Zona SD-WAN", "Ad esempio VPN", "Il gruppo che raccoglie tutti i tunnel della sede. Firewall policy e regole SD-WAN usano la zona, quindi aggiungere un tunnel non richiede nuove policy. Non usare virtual-wan-link, che di solito contiene le linee Internet."],
  "ms.lat": ["Soglia di latenza (ms)", "Ad esempio 150", "Oltre questa latenza media verso l’altra sede il tunnel è fuori SLA e il FortiGate passa a un altro tunnel, se c’è."],
  "ms.jit": ["Soglia di jitter (ms)", "Ad esempio 30", "Variazione della latenza oltre cui il tunnel è fuori SLA. Conta soprattutto per voce e video."],
  "ms.loss": ["Soglia di perdita (%)", "Ad esempio 2", "Percentuale di pacchetti persi oltre cui il tunnel è fuori SLA."],
  "ms.pol": ["Genera le firewall policy", "Consigliato", "LAN verso zona e ritorno su ogni sede; sull’hub (o in full mesh eBGP) anche zona verso zona per il transito; sulle sedi bersaglio dell’health-check il ping verso la loopback. Il servizio è ALL: restringilo a quello che serve."],
  "ms.ipPlan": ["Indirizzi dei tunnel", "In sequenza, oppure per sede come nei piani strutturati", "In sequenza: ogni tunnel prende la prima /30 (o /31) libera della rete dei tunnel. Per sede: la rete dei tunnel si divide in una /24 per sede. Il tunnel tra la sede i e la sede j (i < j) sta nella /24 numero i, nella posizione della sede j, e la sede i prende il primo indirizzo; la /24 zero contiene i router ID. Con 10.255.0.0/16 il tunnel tra la sede 2 e la sede 3 è 10.255.2.5 – 10.255.2.6 e il router ID della sede 3 è 10.255.0.3: dall’indirizzo capisci subito quali sedi collega. Serve una rete con una /24 per sede più una."],
  "ms.grp": ["Come raggruppare i tunnel", "Zona SD-WAN nella maggior parte dei casi", "Zona SD-WAN: ogni tunnel ha il suo IP e la sua sessione BGP; health-check e regole SLA scelgono il tunnel migliore per costo e qualità. Aggregato IPsec: per ogni coppia di sedi i tunnel diventano un’interfaccia sola (config system ipsec-aggregate) con un IP e una sessione BGP; il FortiGate distribuisce il traffico su tutti i tunnel attivi e toglie quelli che il DPD dà per caduti. In questa modalità Fortissimo crea solo tunnel statici, come negli esempi di Fortinet (i membri dial-up non sono documentati): una linea con IP dinamico serve solo se ha un FQDN (DDNS)."],
  "ms.alg": ["Algoritmo di bilanciamento", "L4 nella maggior parte dei casi", "Come l’aggregato distribuisce il traffico tra i tunnel attivi. L4: per sessione, in base a IP e porte, così i pacchetti di una connessione restano sullo stesso tunnel. L3: per coppia di IP sorgente e destinazione. Round-robin: un pacchetto per tunnel a turno; usa tutta la banda ma può riordinare i pacchetti se le linee hanno latenze diverse. Redundant: tutto sul primo tunnel attivo, gli altri restano di riserva; il primo è quello con il costo più basso."],
  "ms.zoneAgg": ["Zona", "Ad esempio VPN", "Una zona del FortiGate (config system zone) con gli aggregati verso tutte le altre sedi. Le firewall policy usano la zona; con intrazone allow il traffico tra due aggregati della stessa zona passa senza policy, così l’hub, o una terza sede in full mesh eBGP, può fare da transito."],
  "ms.polAgg": ["Genera le firewall policy", "Consigliato", "LAN verso zona e ritorno su ogni sede, con gli address NET_<sede> e NET_VPN_REMOTE. Il transito tra aggregati è già permesso da intrazone allow. Il servizio è ALL: restringilo a quello che serve."],
  "ms.names": ["Nomi dei tunnel", "Dal nome della sede o con codici brevi", "Dal nome: T_Milano, oppure T_Milano_12 con più linee. Con i codici ogni sede e ogni linea hanno una sigla: il tunnel si chiama sede e linea locali, trattino, sede e linea remote. MILW-ROML è la linea W (cavo) di Milano verso la linea L (LTE) di Roma; MILS2-ROMW la seconda linea satellitare di Milano verso il cavo di Roma; l’aggregato tra le due sedi si chiama MIL-ROM. I codici si ricavano da soli e puoi cambiarli nelle tabelle delle sedi e delle linee. Un’interfaccia del FortiGate ha al massimo 15 caratteri."],
  "ms.dpdInt": ["Intervallo DPD (secondi)", "Vuoto = predefinito del FortiGate (20 s)", "Ogni quanto il FortiGate ripete il controllo DPD quando un tunnel non risponde (dpd-retryinterval); dopo alcuni tentativi falliti il tunnel è dato per caduto. Un valore basso, come 2–5 s, accorcia il failover: conta soprattutto con l’aggregato IPsec, che toglie un tunnel dal bilanciamento solo quando il DPD lo dichiara caduto."],
  "ms.col.code": ["Codice", "Facoltativo: vuoto = ricavato in automatico", "Il nome è per te: compare nelle schede, nella descrizione dei vicini BGP e nei commenti, e può essere lungo. Il codice è una sigla corta che serve solo a comporre i nomi dei tunnel, perché sul FortiGate un nome di interfaccia ha al massimo 15 caratteri. Vuoto, la sede prende le iniziali del nome (Sede centrale → SC, Filiale 2 → F2) o le prime tre lettere di una parola sola (Milano → MIL). La linea prende il tipo: W cavo o fibra, S satellite, L LTE; una linea privata prende il nome della sua rete (MPLS, RADI…). Dalla seconda linea dello stesso tipo si aggiunge un numero: W, W2. Solo lettere e numeri, al massimo 8."],
  "ms.base": ["Primo numero per membri e regole", "Ad esempio 100", "I membri SD-WAN e le regole generate partono da questo numero, per non sovrascrivere quelli che il FortiGate ha già, come le linee Internet."],
  "ms.col.name": ["Nome", "Ad esempio Milano", "Il nome della sede. Compare nelle schede del risultato, nella descrizione dei vicini BGP, nei commenti delle rotte blackhole e nei nomi dei tunnel delle altre sedi (ad esempio T_Milano). Con i nomi a codici, nei nomi dei tunnel va il codice della sede, non il nome."],
  "ms.col.wan": ["WAN", "Ad esempio wan1", "L’interfaccia Internet del FortiGate da cui partono i tunnel IPsec di questa sede. Scrivila come compare nel FortiGate (wan1, port1, una zona SD-WAN no: serve un’interfaccia)."],
  "ms.col.addr": ["IP pubblico o FQDN", "Ad esempio 203.0.113.10 oppure vpn.sede.it", "L’indirizzo con cui le altre sedi raggiungono questo FortiGate: diventa il gateway remoto dei loro tunnel. Con il tunnel dial-up sull’hub serve solo all’hub, perché sono le filiali a chiamare lui."],
  "ms.col.dyn": ["IP dinamico", "Se l’IP pubblico cambia o la sede è dietro NAT", "La sede non può essere chiamata: è lei a chiamare le altre, che la ricevono su un tunnel dial-up. Due sedi con IP dinamico non possono avere un tunnel diretto tra loro."],
  "ms.col.nets": ["Reti LAN", "Più reti separate da virgola: 192.168.10.0/24, 192.168.11.0/24", "Le reti interne della sede che le altre sedi devono raggiungere: utenti, server, VLAN. Ognuna diventa una riga config network nel BGP di questa sede e una rotta blackhole sulle altre sedi. Il FortiGate annuncia una rete solo se è nella sua tabella di routing (network-import-check): deve esistere come interfaccia, VLAN o rotta statica. Puoi indicare anche una rete più ampia che le comprende, ad esempio 10.10.0.0/16, se esiste una rotta per quella rete."],
  "ms.count": ["Quante sedi", "Da 2 a 30", "Ogni sede è un FortiGate con la sua scheda nel risultato. Con hub e spoke i tunnel sono uno per filiale; in full mesh uno per ogni coppia di sedi, N·(N−1)/2."],
  "ms.topo": ["Topologia", "Hub e spoke nella maggior parte dei casi", "Hub e spoke: ogni filiale ha un tunnel verso la sede centrale e il traffico tra filiali passa dall’hub. Full mesh: un tunnel tra ogni coppia di sedi, il traffico va diretto ma i tunnel crescono in fretta (10 sedi = 45 tunnel). Personalizzata: tunnel e sessioni li decidi tu, una sessione alla volta."],
  "ms.hub": ["Sede centrale (hub)", "La sede con IP pubblico fisso", "Gli spoke chiamano l’hub, quindi deve avere un IP pubblico o un FQDN raggiungibile. Con iBGP l’hub fa anche da route reflector."],
  "ms.hubMode": ["Tunnel sull’hub", "Un tunnel dial-up nella maggior parte dei casi", "Un tunnel dial-up: sull’hub una sola phase1 accetta tutte le filiali, anche con IP dinamico, e una filiale nuova cambia solo il BGP dell’hub. Un tunnel per spoke: una phase1 dedicata a ogni filiale con IP fisso, utile se vuoi WAN o crittografia diverse per filiale; le filiali con IP dinamico usano comunque il tunnel dial-up."],
  "ms.bgpType": ["Tipo di BGP", "iBGP per hub e spoke, eBGP per il full mesh", "iBGP: tutte le sedi nello stesso AS; con hub e spoke l’hub fa da route reflector e passa a ogni filiale le reti delle altre. eBGP: ogni sede ha il suo AS; in full mesh, se un tunnel cade, il traffico può passare da un’altra sede."],
  "ms.baseAs": ["AS di partenza", "Un AS privato, ad esempio 65000", "Con iBGP tutte le sedi usano questo AS. Con eBGP l’hub, o la prima sede, usa questo numero e le altre i successivi: 65001, 65002 e così via."],
  "ms.asManual": ["AS scelti a mano", "Facoltativo", "Spento, gli AS seguono il tipo di BGP. Acceso, imposti l’AS di ogni sede in «Opzioni per sede».", true],
  "ms.advpn": ["Scorciatoie tra filiali (ADVPN)", "Facoltativo", "Quando due filiali si parlano, l’hub propone un tunnel diretto tra loro e il traffico smette di passare dall’hub (auto-discovery). Serve iBGP con il tunnel dial-up sull’hub.", true],
  "ms.pool": ["Rete dei tunnel tra IP fissi", "Ad esempio 169.254.100.0/24", "Da qui Fortissimo propone gli indirizzi dei tunnel tra due sedi con IP fisso, una /30 o una /31 per tunnel. Usa una rete che non esista in nessuna LAN. Puoi sempre cambiare un singolo indirizzo nella tabella «Indirizzi dei tunnel»."],
  "ms.p2pPrefix": ["Maschera dei tunnel tra IP fissi", "/30 nella maggior parte dei casi", "Quanti indirizzi occupa ogni tunnel nella rete qui sopra. /30 usa quattro indirizzi e due sono utilizzabili; /31 ne usa solo due, entrambi utilizzabili. Cambiandola, Fortissimo riassegna gli indirizzi che aveva proposto lui; quelli scritti a mano restano."],
  "ms.loName": ["Nome della loopback", "Ad esempio lo_bgp", "Una loopback è un’interfaccia virtuale del FortiGate che resta sempre su, perché non dipende da nessun cavo o tunnel. Nel BGP serve per far partire la sessione da un indirizzo che non cade (update-source). Qui conta solo per le sessioni «sulle loopback» della topologia personalizzata; se la loopback esiste già, scrivi il suo nome."],
  "ms.loIp": ["IP della loopback", "Ad esempio 10.255.0.1/32, spesso uguale al router ID", "Indirizzo /32 della loopback. Non è indispensabile al BGP: in hub e spoke e in full mesh Fortissimo usa gli IP dei tunnel e le loopback non servono. Servono quando tra due sedi ci sono più collegamenti (ad esempio due tunnel su due WAN) e vuoi una sola sessione BGP che resti su se uno dei due cade: la sessione va da loopback a loopback e ogni FortiGate raggiunge la loopback dell’altro da qualunque tunnel attivo."],
  "ms.dialName": ["Nome del tunnel dial-up", "Al massimo 15 caratteri", "La phase1 dell’hub che accetta le filiali."],
  "ms.overlay": ["Rete delle filiali sul tunnel dial-up", "Da /24 a /30, ad esempio 169.254.200.0/24", "L’hub e le filiali prendono un indirizzo da questa rete sull’interfaccia del tunnel; il BGP usa questi indirizzi come vicini. L’ultimo indirizzo resta libero come remote-ip fittizio dell’hub."],
  "ms.dialIp": ["IP dell’hub sul tunnel dial-up", "Ad esempio 169.254.200.1", "Il vicino BGP che ogni filiale configura."],
  "ms.sites": ["Sedi", "", "Nome, interfaccia WAN, indirizzo pubblico e reti interne di ogni FortiGate. Con il tunnel dial-up sull’hub le filiali non hanno bisogno di un indirizzo pubblico: chiamano loro l’hub."],
  "bn.rid": ["Router ID", "Ad esempio 10.255.0.1", "Identificativo in formato IP, unico per ogni FortiGate. Se manca il FortiGate lo sceglie da solo e può cambiarlo quando cambiano le interfacce; fissarlo rende stabili sessioni e diagnostica.", true],
  "bn.rr": ["Route reflector", "Sull’hub con molte filiali iBGP", "In iBGP un router non ripassa agli altri vicini iBGP le rotte imparate da un vicino iBGP: servirebbero sessioni tra tutte le coppie. Con il route reflector l’hub riflette le rotte a tutte le filiali (route-reflector-client sui vicini)."],
  "bn.ext": ["Peer esterno", "Provider o apparato non FortiGate", "Il nodo non è un FortiGate da configurare: Fortissimo non genera la sua scheda, ma lo usa come vicino degli altri. Serve per provider, router di altri produttori o FortiGate gestiti da altri."],
  "bn.loName": ["Nome della loopback", "Ad esempio lo_bgp", "Interfaccia virtuale sempre attiva da cui parte il BGP (update-source). Massimo 15 caratteri. Se esiste già, scrivi il suo nome: Fortissimo la crea con vdom root."],
  "bn.loIp": ["IP della loopback", "Ad esempio 10.255.0.1", "Indirizzo /32 della loopback. Serve per le sessioni sulle loopback: il BGP resta su anche se cade uno dei collegamenti, purché la loopback sia raggiungibile da un altro. Spesso coincide con il router ID.", true],
  "bn.nets": ["Reti annunciate", "Una per riga, ad esempio 192.168.10.0/24", "Le reti che il nodo annuncia con config network. Il FortiGate le annuncia solo se sono nella sua tabella di routing. Per un lato del tunnel IPsec, vuoto usa le sue reti locali.", true],
  "bn.redisConn": ["Ridistribuisci le reti connesse", "Meglio con una route-map", "Annuncia le reti di tutte le interfacce del FortiGate, comprese WAN e management se non filtri con una route-map. Comodo con molte VLAN."],
  "bn.redisStatic": ["Ridistribuisci le rotte statiche", "Meglio con una route-map", "Annuncia le rotte statiche del FortiGate, compresa la default se non la filtri. Usalo con una route-map che lasci passare solo quello che serve."],
  "bn.redisRm": ["Route-map della ridistribuzione", "Ad esempio RM_REDIST", "Filtra cosa viene ridistribuito. Il nome deve corrispondere a una route-map definita più sotto.", true],
  "bl.a": ["Lato A", "Il primo nodo", "Uno dei due nodi della sessione. Con gli spoke a IP dinamico il lato A è l’hub."],
  "bl.b": ["Lato B", "Il secondo nodo", "L’altro nodo della sessione. Con gli spoke a IP dinamico il lato B è lo spoke."],
  "bl.kind": ["Collegamento", "Tunnel o collegamento fisico", "Tunnel: un’interfaccia IPsec o GRE, con il vicino nella rete del tunnel. Collegamento fisico: porta o VLAN diretta tra i due apparati, ad esempio un cavo tra sedi o la linea del provider."],
  "bl.loop": ["Sessione sulle loopback", "Spento salvo più collegamenti", "La sessione parte dalla loopback invece che dall’interfaccia: con più collegamenti tra gli stessi nodi resta su finché uno funziona. Fortissimo genera la loopback, la rotta verso quella del peer e update-source; in eBGP aggiunge ebgp-enforce-multihop."],
  "bl.if": ["Interfaccia", "Ad esempio VPN_to_B o port3", "L’interfaccia del FortiGate verso il vicino: nome del tunnel o della porta, esattamente come in Network → Interfaces. Massimo 15 caratteri."],
  "bl.ip": ["IP sul collegamento", "Ad esempio 169.254.10.1", "L’indirizzo di questo nodo sul collegamento: l’altro nodo lo usa come indirizzo del vicino. Fortissimo non lo imposta sull’interfaccia, che deve già averlo; per i tunnel IPsec lo imposta la parte IPsec."],
  "bl.dyn": ["Spoke a IP dinamico", "L’hub accetta gli spoke da una rete", "L’hub non conosce in anticipo gli IP degli spoke: accetta il BGP da qualsiasi indirizzo della rete indicata, con neighbor-group e neighbor-range. Il lato A è l’hub."],
  "bl.range": ["Rete degli spoke", "Ad esempio 169.254.20.0/24", "La rete da cui l’hub accetta le sessioni BGP degli spoke. Gli IP di tunnel degli spoke devono stare dentro questa rete."],
  "bl.bfd": ["BFD", "Per accorgersi dei guasti in meno di un secondo", "Il BFD controlla il collegamento molto più spesso del keepalive BGP: se cade, la sessione si chiude subito e le rotte di riserva entrano in gioco. Fortissimo lo attiva sul vicino e sull’interfaccia, su entrambi i lati."],
  "bl.rmIn": ["Route-map in ingresso", "Ad esempio RM_PRIMARY", "Modifica o filtra le rotte ricevute da questo vicino, ad esempio alza la local-preference per preferire questo percorso.", true],
  "bl.rmOut": ["Route-map in uscita", "Ad esempio RM_BACKUP", "Modifica o filtra le rotte annunciate a questo vicino, ad esempio con un prepend per renderlo meno preferito dall’altro lato.", true],
  "bl.plIn": ["Prefix-list in ingresso", "Ad esempio PL_ISP_IN", "Accetta da questo vicino solo i prefissi permessi dalla prefix-list. Verso un provider è indispensabile.", true],
  "bl.plOut": ["Prefix-list in uscita", "Ad esempio PL_ISP_OUT", "Annuncia a questo vicino solo i prefissi permessi. Verso un provider annuncia solo le tue reti pubbliche.", true],
  "bl.max": ["Maximum-prefix", "Ad esempio 10 se il provider manda solo la default", "Se il vicino annuncia più prefissi di questo numero, la sessione viene chiusa. Protegge la tabella di routing dagli errori del peer.", true],
  "bl.def": ["Annuncia la rotta di default", "Di solito dall’hub verso le filiali", "Il FortiGate annuncia 0.0.0.0/0 a questo vicino (capability-default-originate). Utile dall’hub verso le filiali che escono su Internet dalla sede; verso un provider quasi sempre è un errore."],
  "bl.nhs": ["Next-hop-self", "Sull’hub verso le filiali", "Il FortiGate si mette come next-hop nelle rotte che annuncia a questo vicino. Sul route reflector diventa next-hop-self-rr: le filiali ricevono le rotte delle altre filiali con l’hub come next-hop, che sanno raggiungere."],
  "bp.plName": ["Nome", "Ad esempio PL_LAN", "Nome della prefix-list: lettere, numeri, punto, trattino o trattino basso, massimo 35 caratteri. Le sessioni la richiamano con questo nome."],
  "bp.plRules": ["Regole", "Una per riga: permit 10.0.0.0/8 le 24", "Ogni riga è una regola, in ordine: permit o deny, poi una rete CIDR o any, poi facoltativi ge e le. Senza ge e le la rete deve corrispondere esattamente: 0.0.0.0/0 è solo la rotta di default. 10.0.0.0/8 le 24 = tutte le reti dentro 10.0.0.0/8 fino a /24. In fondo c’è un deny implicito."],
  "bp.rmName": ["Nome", "Ad esempio RM_PRIMARY", "Nome della route-map: lettere, numeri, punto, trattino o trattino basso, massimo 35 caratteri. Le sessioni la richiamano con questo nome."],
  "bp.rmRules": ["Regole", "Una per riga: permit match PL_LAN local-pref 200", "Ogni riga è una regola, in ordine: permit o deny, poi facoltativi match <prefix-list>, local-pref <n>, med <n>, prepend <volte, 1–10>, community 65001:100 (più valori separati da virgola) e additive. Una regola senza match vale per tutti i prefissi; quelli che non corrispondono a nessuna regola vengono scartati."]
},
en: {
  "name": ["Project name", "For example Milan–Rome VPN", "Only for you: it is the name you find the project by in «Open» and in the exported JSON file. It is not written to the FortiGate."],
  "fos": ["FortiOS version", "The version running on the FortiGates", "Pick the version shown at the top left of the FortiGate GUI or by «get system status». Some commands exist only from a given version: Fortissimo hides those your version does not know, so you never paste lines that would be rejected. If the two FortiGates run different versions, pick the older one."],
  "side.label": ["Side name", "For example Milan or Customer Smith", "Just a label for you: it appears in the diagram, in route comments and in the summary. It does not change how the VPN works.", true],
  "side.wan": ["WAN interface", "For example wan1", "The FortiGate port connected to the Internet, where VPN packets come in and go out. Type the exact name shown in Network → Interfaces (wan1, wan2, port1…). A wrong name makes the CLI reject the tunnel."],
  "side.ip": ["Public IP", "For example 203.0.113.20", "The fixed Internet address of this FortiGate: the other side uses it to know where to connect. You find it on the WAN interface or from your Internet provider. If the IP changes over time, leave it empty and fill in the dynamic FQDN.", true],
  "side.fqdn": ["Dynamic FQDN", "For example site.fortiddns.com", "A DNS name that always points to the FortiGate’s current IP, useful when the public IP changes. The other side resolves it at every connection. Fill in this or the public IP: at least one is needed. For FortiClient it is the gateway name users see.", true],
  "side.nets": ["Local networks", "One per line, for example 192.168.10.0/24", "The networks behind this FortiGate that the other side must reach. Write them in CIDR format (address/mask). On the other side they become routes to the tunnel; with per-network selectors they also become phase2s. The two sides’ networks must not overlap."],
  "side.tunnel": ["Tunnel name", "Up to 15 characters, for example VPN_Milan", "The VPN name on this FortiGate and also the name of the tunnel’s virtual interface, which you will use in policies and routes. Use letters, digits, dash or underscore, no spaces. FortiOS rejects names longer than 15 characters."],
  "side.tip": ["Tunnel IP", "For example 169.254.10.1", "Optional with static routes, required with BGP. An address on the tunnel interface: it lets you ping from one FortiGate to the other through the VPN and lets BGP talk. Use a small dedicated network that exists in no LAN, for example 169.254.10.0/30, one IP per side.", true],
  "tunPrefix": ["Tunnel network mask", "/30 in most cases", "How big the network holding the two tunnel IPs is. /30 always works; /31 uses only two addresses but some old devices do not handle it. Without tunnel IPs this field has no effect."],
  "auth.method": ["Method", "PSK in most cases", "How the two FortiGates recognise each other. With a PSK you type the same long password on both: simple. With certificates each FortiGate has a certificate signed by a CA: more secure, but you must create and import the certificates first."],
  "psk": ["Pre-shared key (PSK)", "Press Generate for a secure key", "The secret password both sides must have identical, character for character. Use Generate: it creates 32 random characters. Fortissimo never saves or exports it, so copy it somewhere safe before closing the page. If it stays empty, the CLI shows <PSK> to replace."],
  "auth.cert": ["Local certificate", "Name of the certificate already imported on the FortiGate", "The certificate this FortiGate proves its identity with. It must already exist in System → Certificates: type the exact name shown there."],
  "auth.peer": ["PKI peer user", "For example PEER_ROME", "An object Fortissimo creates to tell the FortiGate which certificate to accept from the other side: it holds the CA and optionally the certificate name. Pick any name."],
  "auth.ca": ["Peer CA", "Name of the CA already imported", "The authority that signed the other side’s certificate. Its certificate must be imported on this FortiGate (System → Certificates, CA section). Without it the tunnel does not authenticate."],
  "auth.cn": ["Peer Common Name", "For example fgt-rome.company.com", "If set, the FortiGate accepts only the certificate with this name. If empty it accepts any certificate signed by the given CA: convenient, but less strict.", true],
  "ident.networkId": ["Network ID", "0 if there is only one IKEv2 dial-up tunnel", "Needed only when the same WAN has several IKEv2 dial-up tunnels (for example one for staff and one for consultants). The client sends this number and the FortiGate picks the tunnel with the same number. Without it everyone lands on the first tunnel and gets credential errors. 0 = off; each tunnel needs a different number, 1 to 255."],
  "ident.usedIds": ["Network IDs already in use", "For example 0, 1", "Type the Network IDs of the other IKEv2 dial-up tunnels already on the same WAN, comma separated. It is not written to the configuration: the checks only use it to warn you if you pick a number already taken. Tunnels without a Network ID count as 0.", true],
  "ident.localid": ["Branch local ID", "For example branch-rome", "A name the branch introduces itself with to the hub. Needed if the hub must accept only this branch (Accepted peers = only the given ID) or to tell several branches apart. If empty the branch introduces itself with its IP.", true],
  "ident.peerMode": ["Peers accepted by the hub", "Only the given ID is safer", "With «any» the hub accepts anyone who knows the PSK. With «only the given peer ID» it accepts only the branch presenting that local ID: another device with the same PSK stays out."],
  "crypto.ike": ["IKE version", "IKEv2", "IKE is the protocol that negotiates the VPN. Use IKEv2: it is newer, faster and sturdier. IKEv1 is only for old devices that do not know IKEv2; FortiClient no longer supports it from 7.4.4."],
  "crypto.mode": ["IKEv1 mode", "Main", "Exists only with IKEv1. Main is the safe choice. Aggressive sends the identity in clear text and lets attackers try the PSK offline: use it only if an old peer really requires it."],
  "crypto.p1": ["Phase1 proposals", "For example aes256-sha256", "The algorithms protecting the initial «handshake» between the two sides. At least one proposal must match on both sides; Fortissimo uses the same on both. GCM and ChaCha20 entries work only with IKEv2."],
  "crypto.dh1": ["Phase1 Diffie-Hellman groups", "20 (recommended) or 21", "The DH group sets how strong the key exchange is. 20 or 21 are modern and safe; below 14 they are weak. Better a single group, the same on both sides: with more than one, the first attempt may fail and negotiation takes an extra round."],
  "crypto.life1": ["Phase1 lifetime (seconds)", "86400, that is 24 hours", "How often the two sides renew the phase1 keys. The normal value is 86400 seconds (one day). No need to change it; if you do, use the same on both sides."],
  "crypto.p2": ["Phase2 proposals", "For example aes256gcm", "The algorithms that encrypt the actual traffic. aes256gcm is the most efficient on recent FortiGates because it encrypts and checks integrity in one go. One proposal in common between the sides is enough."],
  "crypto.pfs": ["Perfect Forward Secrecy", "On", "With PFS every traffic key renewal creates brand-new keys: if a key were ever stolen, past traffic would stay protected. Keep it on; it must be on or off on both sides alike."],
  "crypto.dh2": ["Phase2 DH groups", "Same as phase1", "Used only when PFS is on. Use the same as phase1 and the same on both sides."],
  "crypto.life2": ["Phase2 lifetime (seconds)", "43200, that is 12 hours", "How often the keys encrypting traffic are renewed. 43200 seconds (12 hours) is the FortiOS default. Use the same on both sides."],
  "sel.mode": ["Selectors", "All traffic (0.0.0.0/0)", "Selectors say which networks may cross the VPN. Between two FortiGates choose «all traffic»: simplest, then routes and policies decide what really passes. Choose «one phase2 per network pair» only if the other side is a device that requires it, or if you want to limit networks at VPN level."],
  "route.on": ["Static routes", "On", "Routes tell the FortiGate to use the tunnel to reach the other side’s networks. Without routes the VPN may be up but no traffic enters it. Turn this off only if routes are handled elsewhere, for example by SD-WAN."],
  "route.distance": ["Administrative distance", "10", "If there are several paths to the same network, the FortiGate picks the one with the lowest distance. 10 is the normal value. Raise it only if another path must take precedence over the VPN."],
  "route.bh": ["Blackhole routes", "On", "If the tunnel drops, the VPN route disappears and traffic to the other site could leave on the Internet unencrypted. The blackhole is a backup route that drops those packets instead. Keep it on."],
  "route.bhDistance": ["Blackhole distance", "254", "It must be higher than the VPN route distance: then the blackhole applies only when the tunnel is down. 254 is fine almost always."],
  "dial.auth": ["Users", "Where credentials are checked", "Local: users created on the FortiGate, ideal for a few users, with FortiToken. LDAP: Active Directory users. RADIUS: a server such as NPS checks credentials (MFA possible). SAML Entra ID: Microsoft 365 sign-in with its MFA, but it needs more steps in Entra."],
  "dial.group": ["FortiGate user group", "For example VPN_USERS", "Name of the group Fortissimo creates on the FortiGate: only its members can connect to this VPN. Pick any name; if it exists it is updated."],
  "dial.users": ["Local users in the group", "For example john.smith, jane.doe", "Names of the local users to put in the group, comma separated. They must already exist in User & Authentication → User Definition, with password and ideally FortiToken: Fortissimo does not create them."],
  "dial.ldapServer": ["LDAP server", "For example AD_LDAP", "Name of the LDAP server object on the FortiGate. With «Create the LDAP server too» Fortissimo creates it with this name; otherwise it must already exist in User & Authentication → LDAP Servers."],
  "dial.ldapDN": ["AD group DN", "CN=VPN,OU=Groups,DC=company,DC=local", "The «full path» of the Active Directory group allowed on the VPN. Find it in AD Users and Computers: enable View → Advanced Features, open the group → Attribute Editor → distinguishedName, and copy it exactly."],
  "dial.radiusServer": ["RADIUS server", "For example NPS", "Name of the RADIUS server object on the FortiGate. With «Create the RADIUS server too» Fortissimo creates it with this name; otherwise it must already exist in User & Authentication → RADIUS Servers."],
  "dial.samlServer": ["SAML server name", "For example entra-vpn", "Name of the object linking the FortiGate to Entra ID. Pick any name without spaces."],
  "dial.samlPort": ["SAML port", "For example 9443", "The port where FortiClient opens the Microsoft sign-in before building the tunnel. It must be free: do not use the FortiGate HTTPS admin port or the SSL-VPN port. FortiClient needs the same port (already in the generated file)."],
  "dial.tenant": ["Entra tenant ID", "A code like e559b5c4-…", "The identifier of your Microsoft organisation. Find it in Entra admin center → Overview → Tenant ID. Fortissimo uses it to build Microsoft’s sign-in addresses."],
  "dial.groupId": ["Entra group object ID", "A code like aa4932cf-…", "The ID of the Entra group whose members may use the VPN. Find it in Entra → Groups → the group → Object ID. The FortiGate lets in only users who have this ID among their groups."],
  "dial.idpCert": ["IdP certificate", "For example REMOTE_Cert_1", "The Entra certificate you downloaded (Base64) and imported on the FortiGate as a Remote Certificate. Type the name the FortiGate gave it. It proves sign-in answers really come from Microsoft."],
  "dial.spCert": ["SP certificate", "Fortinet_Factory for the first test", "The certificate the FortiGate presents during SAML sign-in. For testing Fortinet_Factory is fine (FortiClient shows a warning); in production use a certificate valid for the FQDN, for example Let’s Encrypt."],
  "dial.authCert": ["Authentication certificate", "For example le-vpn", "If set, Fortissimo sets auth-cert, the certificate FortiClient sees on the SAML port: with a valid certificate the security warning disappears. Careful: it is a global FortiGate setting, check first that nothing else uses it. If empty, it is not touched.", true],
  "dial.poolStart": ["Pool: first IP", "For example 10.254.10.10", "Connected clients get an address from this range. Use a network dedicated to the VPN that exists in no LAN, otherwise addresses will clash."],
  "dial.poolEnd": ["Pool: last IP", "For example 10.254.10.210", "Last address of the range. The number of addresses between first and last is the maximum number of clients connected at once."],
  "dial.dns1": ["DNS 1", "For example the domain controller", "The DNS server clients use while on VPN, usually the internal DNS or the domain controller. Without it clients cannot resolve internal server names.", true],
  "dial.dns2": ["DNS 2", "Second internal DNS", "Backup DNS server, used if the first does not answer.", true],
  "dial.split": ["Routing", "Split tunnel in most cases", "Split tunnel: only traffic to company networks goes through the VPN, while the Internet goes out of the home connection. Full tunnel: browsing also goes through the FortiGate, more controllable but slower, and it needs a policy to the Internet."],
  "dial.client": ["Connection name", "For example Company VPN", "The name users see in the FortiClient VPN list. Pick something clear."],
  "dial.authTimeout": ["Time for MFA (seconds)", "For example 60", "How long the FortiGate waits for the credential check. The factory value is only 5 seconds: too short to read a FortiToken code or approve a notification, so sign-in fails. 60 is a good value; the maximum is 300. It is a global setting (remoteauthtimeout). If empty it is not touched.", true],
  "dial.saveUser": ["Remember the username", "In FortiClient", "When on, FortiClient remembers the username between connections. The password is not saved. Turn it off on shared PCs."],
  "dial.ldapCreate": ["Create the LDAP server too", "Turn off if it already exists", "When on, Fortissimo also generates the FortiGate link to the domain controller (config user ldap). If the LDAP server already exists on the FortiGate, turn it off and just type its name."],
  "dial.ldapIp": ["Domain controller address", "For example 192.168.10.10", "IP or name of the domain controller the FortiGate queries. The FortiGate must reach it on port 389 (or 636 with LDAPS)."],
  "dial.ldapCnid": ["Username attribute", "sAMAccountName", "How users type their name at sign-in. sAMAccountName: the short name (john.smith). userPrincipalName: the full address (john.smith@company.com). The FortiGate factory value, cn, does not match Active Directory sign-in names."],
  "dial.ldapBase": ["Base DN", "For example DC=company,DC=local", "Where the FortiGate starts looking for users. Use the domain root: if the domain is company.local type DC=company,DC=local. Then it finds users in any folder (OU)."],
  "dial.ldapBind": ["Bind account DN", "CN=svc-fortigate,OU=Services,DC=company,DC=local", "The service account the FortiGate uses to log into Active Directory and search users. It needs the full path (distinguishedName), not just the name: copy it from the user’s Attribute Editor. Create a dedicated user, without privileges and with a non-expiring password."],
  "ldapPwd": ["Bind account password", "The service account password", "It must match the account password in Active Directory. Fortissimo never saves or exports it; if empty, the CLI shows a placeholder to replace.", true],
  "dial.ldapSecure": ["Secure connection", "LDAPS if the DC has a certificate", "None: the service account password travels in clear text on the internal network. LDAPS: everything encrypted on port 636, but the domain controller needs a certificate and its CA must be imported on the FortiGate. STARTTLS: like LDAPS but on port 389."],
  "dial.ldapNested": ["Nested groups", "Only if you use groups inside groups", "Turn it on if users are not directly in the VPN group but in another group that belongs to it. If users are direct members, leave it off."],
  "dial.radiusCreate": ["Create the RADIUS server too", "Turn off if it already exists", "When on, Fortissimo also generates the FortiGate link to the RADIUS server (config user radius). If it already exists on the FortiGate, turn it off and just type its name."],
  "dial.radiusIp": ["RADIUS server address", "For example 192.168.10.20", "IP or name of the RADIUS server (for example NPS). The FortiGate must reach it on UDP port 1812."],
  "radiusPwd": ["Shared secret", "Same as the RADIUS client on NPS", "The password the FortiGate and the RADIUS server use between them. It must match the one set on the server for the FortiGate client. Fortissimo never saves it; if empty, the CLI keeps a placeholder.", true],
  "dial.radiusTimeout": ["Server timeout (seconds)", "For example 60 with MFA", "How long the FortiGate waits for the RADIUS server. The factory value is a few seconds: if the server also asks for a second factor (app or SMS), raise it, or sign-in times out before the user answers. If empty the factory value stays.", true],
  "bgp.on": ["Use BGP", "Off if you have few networks", "BGP is an automatic way to exchange networks: each side announces its own and the FortiGate notices at once if the tunnel drops. Worth it with many networks, two Internet lines or many branches. For two sites with few networks static routes are simpler."],
  "bgp.asA": ["Side A AS", "For example 65001", "A number identifying side A for BGP. Use private numbers 64512 to 65534. With different numbers on the two sides (recommended) the session is eBGP; with the same number it is iBGP."],
  "bgp.asB": ["Side B AS", "For example 65002", "Side B’s BGP number. Usually different from side A."],
  "bgp.ridA": ["Side A router ID", "For example 10.0.0.1", "An identifier in IP address format, unique per FortiGate. If empty the FortiGate picks one; fixing it stops it changing when interfaces change.", true],
  "bgp.ridB": ["Side B router ID", "For example 10.0.0.2", "As for side A: optional, but it must differ from side A’s.", true],
  "bgp.overlay": ["Overlay network", "For example 169.254.20.0/24", "A small network used only for the hub and branch tunnel IPs, not for PCs. The hub accepts BGP from every address of this network. The last address is reserved and must not be assigned to anyone."],
  "bgp.tipHub": ["Hub tunnel IP", "For example 169.254.20.1", "The hub’s address inside the overlay network. Branches use it to talk BGP with the hub."],
  "bgp.tipBranch": ["Branch tunnel IP", "For example 169.254.20.2", "This branch’s address inside the overlay network. Each branch needs a different one."],
  "bgp.keepalive": ["Keepalive (seconds)", "Empty = 60", "How often, in seconds, the two sides exchange a sign of life. Low values (for example 10) notice failures sooner. If empty the FortiOS value stays.", true],
  "bgp.holdtime": ["Holdtime (seconds)", "Empty = 180", "After how many seconds without signs the neighbour is considered down. It must be at least three times the keepalive. If empty the FortiOS value stays.", true],
  "bgp.soft": ["Soft reconfiguration", "On", "The FortiGate keeps a copy of received routes: if you change a filter it does not have to drop and rebuild the session. It costs a little memory; keep it on."],
  "bgp.ldf": ["Link-down failover", "On", "If the tunnel interface goes down, the BGP session closes at once instead of waiting for the holdtime: backup routes take over within moments."],
  "bgp.gr": ["Graceful restart", "Off unless clustered", "Keeps routes while the BGP process restarts or the cluster fails over to the other FortiGate. Useful with FortiGates in HA; otherwise leave it off."],
  "bgpPwd": ["BGP password", "Same on both sides", "Protects the BGP session from unauthorised neighbours. It must be identical on both sides. It is never saved or exported.", true],
  "dual.on": ["Second tunnel on another line", "Only if you have two Internet lines", "Creates a second tunnel through side A’s second Internet line: if the first line drops, the VPN keeps working on the second. Side B may have one or two lines."],
  "dual.aWan": ["Second line interface", "For example wan2", "The FortiGate A port connected to the second Internet line."],
  "dual.aIp": ["Second line public IP", "For example 198.51.100.50", "The Internet address of side A’s second line: side B uses it to build the second tunnel. This or the FQDN is needed.", true],
  "dual.aFqdn": ["Second line FQDN", "If the IP is not fixed", "A DNS name pointing to the second line’s IP, if that IP changes. This or the IP is needed.", true],
  "dual.aTunnel": ["Second tunnel name", "For example VPN2_to_B", "Name of the second tunnel on side A. Up to 15 characters, different from the first."],
  "dual.aTip": ["Second tunnel IP", "For example 169.254.10.5", "Address on the second tunnel interface. Optional with static routes, required with BGP. Use a different network from the first tunnel.", true],
  "dual.bWan": ["Second line interface", "Only if side B has two lines", "If side B also has a second line, type its port here. If side B has a single line leave it empty: the second tunnel lands on its only WAN.", true],
  "dual.bIp": ["Second line public IP", "Only if side B has two lines", "The Internet address of side B’s second line. Leave empty if side B has a single line.", true],
  "dual.bFqdn": ["Second line FQDN", "If the IP is not fixed", "DNS name of side B’s second line, if the IP changes.", true],
  "dual.bTunnel": ["Second tunnel name", "For example VPN2_to_A", "Name of the second tunnel on side B. Up to 15 characters, different from the first."],
  "dual.bTip": ["Second tunnel IP", "For example 169.254.10.6", "Optional with static routes, required with BGP. It must be in the same small network as side A’s second tunnel IP.", true],
  "dual.mode": ["Second tunnel use", "Backup in most cases", "Backup: both tunnels stay up, everything goes through the first and the second takes over if the first drops. Standby: the second tunnel stays down and comes up only when the first drops (monitor option); it uses less but failover is a little slower. Parallel: traffic is split across both, useful if the lines are similar and you want to add up their bandwidth."],
  "dual.backupDist": ["Backup tunnel distance", "For example 20", "It must be higher than the main routes’ distance (usually 10) and lower than the blackholes’ (254). Then the second tunnel is used only when the first is down."],
  "trans.mode": ["IKE protocol", "UDP", "Normally the VPN uses UDP ports 500 and 4500. Some networks (hotels, guest Wi-Fi, companies) block them: with TCP the VPN still gets through, a bit slower. Automatic mode, which tries UDP then TCP, exists only from FortiOS 7.6."],
  "trans.port": ["TCP port", "For example 10443", "The TCP port where the FortiGate receives the VPN over TCP. It is a global setting: changing it drops every IPsec tunnel for a moment. It cannot match the HTTPS admin port or a VIP."],
  "trans.threshold": ["Fallback threshold (seconds)", "Empty = FortiOS value", "After how many seconds without a UDP answer the client tries TCP. 1 to 300.", true],
  "dial.exclude": ["Networks kept out of the tunnel", "One per line, for example 192.168.1.0/24", "With a full tunnel everything goes through the FortiGate. Here you list the networks that must stay out, reached directly from the user’s home: for example a cloud service that must not go through the office. If empty, everything goes through.", true],
  "dial.localLan": ["Allow the home network", "User’s printer, NAS, TV", "With a full tunnel users lose access to devices on their own home network. When on, FortiClient lets them reach the local LAN. It is set in the FortiClient file."],
  "dial.domains": ["Internal domains (split DNS)", "For example company.local", "Names ending with these domains are resolved by the VPN DNS; everything else by the user’s home DNS. Browsing stays fast and internal servers are found. Separate them with spaces or commas. Available from FortiOS 7.4.1. If empty, the VPN DNS resolves everything.", true],
  "dial.suffix": ["DNS suffixes", "For example company.local", "The client appends these suffixes to short names: typing «server01» finds «server01.company.local». Available from FortiOS 7.6.4.", true],
  "gwm.mode": ["Accept connections from", "Anywhere, unless security needs it", "Restricts who can even start negotiating. «From a network» or «from a range» if clients or branches have known IPs; «from a country» to block attempts from abroad. Needs FortiOS 7.4.4. Careful: anyone left out cannot connect even with the right credentials."],
  "gwm.subnet": ["Allowed network", "For example 203.0.113.0/24", "Only Internet addresses inside this network can connect. CIDR format."],
  "gwm.start": ["First allowed IP", "For example 203.0.113.10", "First Internet address of the range to accept connections from."],
  "gwm.end": ["Last allowed IP", "For example 203.0.113.50", "Last address of the range."],
  "gwm.country": ["Allowed country", "Two-letter code, for example IT", "Only addresses that the FortiGuard GeoIP database assigns to this country can connect. Users abroad, or on a mobile network exiting abroad, are left out."],
  "dual.holdType": ["Return to the primary tunnel", "At once in most cases", "When the primary line comes back, the FortiGate moves back to the first tunnel. «At once» does it as soon as possible; «after a delay» waits a few seconds, useful if the primary line keeps flapping."],
  "dual.holdDelay": ["Delay (seconds)", "For example 60", "How many seconds of stable primary line before moving back to it."],
  "fec.on": ["Error correction (FEC)", "Only on lossy lines", "For every group of packets the FortiGate sends a few correction packets: if a packet is lost, the other side rebuilds it without retransmission. Useful on 4G, satellite or radio links, for voice and video. It costs bandwidth and turns off the tunnel’s hardware acceleration. It is enabled on both sides."],
  "fec.base": ["Base packets", "Empty = 20", "After how many normal packets the correction group is sent. 1 to 40.", true],
  "fec.redundant": ["Correction packets", "Empty = 10", "How many correction packets per group. More of them recover more losses and use more bandwidth: with 20 base and 10 correction traffic grows by about 50%. 1 to 20.", true],
  "bx.autoLink": ["When you add a node", "To the hub in most cases", "To the hub: the new node gets a session and an IPsec tunnel to the route reflector. To everyone: a session and a tunnel to every existing FortiGate (full mesh, N·(N−1)/2 tunnels). Manually: the node starts with no sessions. Tunnels and sessions stay editable one by one."],
  "bx.pool": ["Network for tunnel IPs", "For example 169.254.100.0/24", "Fortissimo takes a /30 from this network for each generated tunnel between FortiGates with a public IP. Use a network that exists in no LAN. IPs stay editable in the session."],
  "bn.wan": ["WAN interface", "For example wan1", "The FortiGate Internet port where generated IPsec tunnels start. Each tunnel can use another one."],
  "bn.pubIp": ["Public IP", "For example 203.0.113.20", "The address the other FortiGates connect to. If the IP changes use the FQDN, or mark the node as dynamic IP.", true],
  "bn.fqdn": ["FQDN", "For example site.fortiddns.com", "DNS name of the FortiGate when the public IP changes: the other sides use remotegw-ddns.", true],
  "bn.dyn": ["Dynamic IP or behind NAT", "Nobody can call this FortiGate", "The node calls the others but cannot be called. Toward a node with a public IP the tunnel becomes dial-up: the other side acts as hub with a shared tunnel and accepts BGP with neighbor-range."],
  "bn.dialName": ["Dial-up tunnel name", "For example DIAL_BGP", "The shared tunnel this FortiGate accepts every dynamic-IP spoke on. Up to 15 characters."],
  "bn.overlay": ["Dynamic spoke network", "For example 169.254.200.0/24", "Network the hub and the dynamic spokes take their tunnel IP from. The hub accepts BGP from this whole network; the last address is reserved."],
  "bn.dialIp": ["Hub IP in the spoke network", "For example 169.254.200.1", "The dial-up tunnel address on this FortiGate: spokes use it as BGP neighbor."],
  "bl.ipsec": ["Generate the IPsec tunnel", "On for FortiGates linked over the Internet", "Fortissimo creates phase1, phase2 and tunnel IP on both nodes, with the IPsec section cryptography and the single PSK. Turn it off if the tunnel already exists."],
  "bl.tname": ["Tunnel name", "Up to 15 characters", "Name of the phase1 and of the tunnel interface on this FortiGate. Proposed automatically, you can change it."],
  "bl.twan": ["Tunnel WAN", "Empty = the tunnel’s line, in grey", "Interface this tunnel starts from. Change it to run a second tunnel over another line."],
  "bl.tgw": ["Remote gateway", "Empty = the other site’s line address, in grey", "The address this FortiGate connects to. Change it when the other node has several lines and this tunnel must use another one.", true],
  "bl.tip": ["Tunnel IP", "Assigned automatically", "Tunnel interface address on this FortiGate: the other side uses it as BGP neighbor. The two IPs sit in the same /30."],
  "bl.cOwn": ["Own cryptography", "Off = the IPsec section one", "Turn it on if this tunnel must use different proposals or DH groups, for example toward an older device. It starts from a copy of the IPsec section cryptography."],
  "bx.multipath": ["Multipath", "With several sessions to the same site", "With several sessions to the same site the FortiGate uses all equal paths together instead of a single one (ibgp-multipath and ebgp-multipath). Useful with two parallel tunnels; off when a path must only be a backup."],
  "bn.name": ["Name", "For example Milan or Provider", "Identifies the node in the diagram, in the neighbor description (set description) and in the tab name. For an IPsec tunnel side, empty uses that side’s name.", true],
  "bn.as": ["AS", "For example 65001", "The node’s BGP number. Same AS on two nodes = iBGP session, different ASes = eBGP. Between your sites use private ASes (64512–65534); toward a provider use the AS agreed with it."],
  "ms.sdwan": ["Several lines per site", "Optional", "Each site can have up to 8 lines (fibre, FWA, LTE, Starlink, private lines such as MPLS, radio links or satellite). Fortissimo creates a tunnel for each line pair between two sites and groups them: in an SD-WAN zone, with health-checks and rules picking the best tunnel, or in one IPsec aggregate per site pair, which uses them all together.", true],
  "ms.col.lan": ["LAN interface", "For example lan, internal or a VLAN", "The FortiGate interface the site’s internal network sits on. The generated firewall policies go from here to the SD-WAN zone and back."],
  "ms.col.type": ["Line type", "Cable, satellite, LTE/5G or private", "The type gives the line letter in code names (W cable or fibre, S satellite, L LTE) and drops impossible pairs automatically. A private line (MPLS, radio link, dedicated satellite link) reaches only the private lines on the same network: type the network name in the field that appears, the same on every site sharing it (for example MPLS1, or SAT-MIL for a dedicated link between two sites). As address use the site’s IP on that network. Cable, satellite and LTE reach each other over the Internet; use the cost to decide how much to use them."],
  "ms.col.cost": ["Cost", "0 for the main line, more for the others", "A tunnel’s cost is the sum of its two lines’ costs. Among the tunnels meeting the SLA thresholds the FortiGate uses the cheapest: give metered lines such as LTE a high cost."],
  "ms.zone": ["SD-WAN zone", "For example VPN", "The group holding every tunnel of the site. Firewall policies and SD-WAN rules use the zone, so adding a tunnel needs no new policy. Do not use virtual-wan-link, which usually holds the Internet lines."],
  "ms.lat": ["Latency threshold (ms)", "For example 150", "Above this average latency to the other site the tunnel is out of SLA and the FortiGate moves to another tunnel, if any."],
  "ms.jit": ["Jitter threshold (ms)", "For example 30", "Latency variation beyond which the tunnel is out of SLA. It matters most for voice and video."],
  "ms.loss": ["Packet loss threshold (%)", "For example 2", "Share of lost packets beyond which the tunnel is out of SLA."],
  "ms.pol": ["Generate the firewall policies", "Recommended", "LAN to zone and back on every site; on the hub (or in an eBGP full mesh) also zone to zone for transit; on the health-check target sites the ping to the loopback. The service is ALL: narrow it to what you need."],
  "ms.ipPlan": ["Tunnel addresses", "In sequence, or per site as in structured plans", "In sequence: each tunnel takes the first free /30 (or /31) of the tunnel network. Per site: the tunnel network is split into one /24 per site. The tunnel between site i and site j (i < j) sits in /24 number i, at site j’s position, and site i takes the first address; /24 zero holds the router IDs. With 10.255.0.0/16 the tunnel between site 2 and site 3 is 10.255.2.5 – 10.255.2.6 and site 3’s router ID is 10.255.0.3: the address tells at once which sites it joins. It needs a network with one /24 per site plus one."],
  "ms.grp": ["How to group the tunnels", "SD-WAN zone in most cases", "SD-WAN zone: each tunnel has its own IP and BGP session; health-checks and SLA rules pick the best tunnel by cost and quality. IPsec aggregate: for each site pair the tunnels become a single interface (config system ipsec-aggregate) with one IP and one BGP session; the FortiGate spreads traffic over every live tunnel and drops the ones DPD declares dead. In this mode Fortissimo creates static tunnels only, as in Fortinet’s examples (dial-up members are not documented): a dynamic-IP line works only if it has an FQDN (DDNS)."],
  "ms.alg": ["Balancing algorithm", "L4 in most cases", "How the aggregate spreads traffic over the live tunnels. L4: per session, by IPs and ports, so a connection’s packets stay on the same tunnel. L3: per source and destination IP pair. Round-robin: one packet per tunnel in turn; it uses all the bandwidth but may reorder packets when the lines have different latencies. Redundant: everything on the first live tunnel, the others stay as backup; the first is the one with the lowest cost."],
  "ms.zoneAgg": ["Zone", "For example VPN", "A FortiGate zone (config system zone) holding the aggregates to every other site. Firewall policies use the zone; with intrazone allow traffic between two aggregates of the same zone passes without a policy, so the hub, or a third site in an eBGP full mesh, can act as transit."],
  "ms.polAgg": ["Generate the firewall policies", "Recommended", "LAN to zone and back on every site, with the NET_<site> and NET_VPN_REMOTE addresses. Transit between aggregates is already allowed by intrazone allow. The service is ALL: narrow it to what you need."],
  "ms.names": ["Tunnel names", "From the site name or with short codes", "From the name: T_Milan, or T_Milan_12 with several lines. With codes every site and line has a tag: a tunnel is named local site and line, dash, remote site and line. MILW-ROML is Milan’s line W (cable) toward Rome’s line L (LTE); MILS2-ROMW is Milan’s second satellite line toward Rome’s cable; the aggregate between the two sites is MIL-ROM. Codes are derived automatically and you can change them in the site and line tables. A FortiGate interface has 15 characters at most."],
  "ms.dpdInt": ["DPD interval (seconds)", "Empty = FortiGate default (20 s)", "How often the FortiGate retries the DPD check when a tunnel does not answer (dpd-retryinterval); after a few failed attempts the tunnel is declared dead. A low value, such as 2–5 s, shortens the failover: it matters most with the IPsec aggregate, which drops a tunnel from the balancing only when DPD declares it dead."],
  "ms.col.code": ["Code", "Optional: empty = derived automatically", "The name is for you: it shows in the tabs, in the BGP neighbor description and in comments, and it can be long. The code is a short tag used only to build tunnel names, because a FortiGate interface name has 15 characters at most. When empty, the site takes the initials of its name (Head office → HO, Branch 2 → B2) or the first three letters of a single word (Milan → MIL). The line takes its type: W cable or fibre, S satellite, L LTE; a private line takes its network name (MPLS, RADI…). From the second line of the same type a number is added: W, W2. Letters and digits only, 8 at most."],
  "ms.base": ["First number for members and rules", "For example 100", "The generated SD-WAN members and rules start from this number, so they do not overwrite the FortiGate’s existing ones, such as the Internet lines."],
  "ms.col.name": ["Name", "For example Milan", "The site name. It appears in the output tabs, in the BGP neighbor description, in the blackhole route comments and in the other sites’ tunnel names (for example T_Milan). With code names, tunnel names use the site code instead of the name."],
  "ms.col.wan": ["WAN", "For example wan1", "The FortiGate Internet interface this site’s IPsec tunnels leave from. Write it as it appears on the FortiGate (wan1, port1; not an SD-WAN zone: an interface is needed)."],
  "ms.col.addr": ["Public IP or FQDN", "For example 203.0.113.10 or vpn.site.com", "The address the other sites use to reach this FortiGate: it becomes the remote gateway of their tunnels. With the dial-up tunnel on the hub only the hub needs it, because the branches call the hub."],
  "ms.col.dyn": ["Dynamic IP", "If the public IP changes or the site is behind NAT", "The site cannot be called: it calls the others, which accept it on a dial-up tunnel. Two sites with a dynamic IP cannot have a direct tunnel between them."],
  "ms.col.nets": ["LAN networks", "Several networks separated by commas: 192.168.10.0/24, 192.168.11.0/24", "The site’s internal networks the other sites must reach: users, servers, VLANs. Each one becomes a config network line in this site’s BGP and a blackhole route on the other sites. The FortiGate announces a network only if it is in its routing table (network-import-check): it must exist as an interface, VLAN or static route. You can also give a wider network covering them, for example 10.10.0.0/16, if a route for that network exists."],
  "ms.count": ["How many sites", "From 2 to 30", "Each site is a FortiGate with its own tab in the output. With hub and spoke there is one tunnel per branch; in full mesh one per pair of sites, N·(N−1)/2."],
  "ms.topo": ["Topology", "Hub and spoke in most cases", "Hub and spoke: each branch has a tunnel to the central site and traffic between branches goes through the hub. Full mesh: a tunnel between every pair of sites, traffic goes direct but tunnels grow fast (10 sites = 45 tunnels). Custom: you decide tunnels and sessions, one session at a time."],
  "ms.hub": ["Central site (hub)", "The site with a fixed public IP", "Spokes call the hub, so it needs a reachable public IP or FQDN. With iBGP the hub is also the route reflector."],
  "ms.hubMode": ["Tunnels on the hub", "One dial-up tunnel in most cases", "One dial-up tunnel: on the hub a single phase1 accepts every branch, dynamic IPs included, and a new branch changes only the hub’s BGP. One tunnel per spoke: a dedicated phase1 for each branch with a fixed IP, useful if you want different WANs or cryptography per branch; branches with a dynamic IP still use the dial-up tunnel."],
  "ms.bgpType": ["BGP type", "iBGP for hub and spoke, eBGP for full mesh", "iBGP: every site in the same AS; with hub and spoke the hub is the route reflector and passes each branch the networks of the others. eBGP: each site has its own AS; in a full mesh, if a tunnel drops, traffic can go through another site."],
  "ms.baseAs": ["Starting AS", "A private AS, for example 65000", "With iBGP every site uses this AS. With eBGP the hub, or the first site, uses this number and the others the next ones: 65001, 65002 and so on."],
  "ms.asManual": ["Hand-picked AS numbers", "Optional", "Off, AS numbers follow the BGP type. On, you set each site’s AS in «Per-site options».", true],
  "ms.advpn": ["Shortcuts between branches (ADVPN)", "Optional", "When two branches talk, the hub offers them a direct tunnel and traffic stops going through the hub (auto-discovery). Needs iBGP with the dial-up tunnel on the hub.", true],
  "ms.pool": ["Network for fixed-IP tunnels", "For example 169.254.100.0/24", "Fortissimo proposes the addresses of tunnels between two fixed-IP sites from here, one /30 or /31 per tunnel. Use a network that exists in no LAN. You can always change a single address in the «Tunnel addresses» table."],
  "ms.p2pPrefix": ["Mask of fixed-IP tunnels", "/30 in most cases", "How many addresses each tunnel takes in the network above. /30 uses four addresses, two of them usable; /31 uses just two, both usable. When you change it, Fortissimo reassigns the addresses it proposed; hand-typed ones stay."],
  "ms.loName": ["Loopback name", "For example lo_bgp", "A loopback is a FortiGate virtual interface that is always up, because it depends on no cable or tunnel. In BGP it lets the session start from an address that never goes down (update-source). Here it matters only for «over loopbacks» sessions in the custom topology; if the loopback already exists, type its name."],
  "ms.loIp": ["Loopback IP", "For example 10.255.0.1/32, often the same as the router ID", "The loopback’s /32 address. BGP does not need it: in hub and spoke and full mesh Fortissimo uses the tunnel IPs and loopbacks are not needed. They help when two sites have several links (for example two tunnels over two WANs) and you want a single BGP session that stays up when one drops: the session runs loopback to loopback and each FortiGate reaches the other’s loopback over any tunnel that is up."],
  "ms.dialName": ["Dial-up tunnel name", "15 characters at most", "The hub phase1 that accepts the branches."],
  "ms.overlay": ["Branch network on the dial-up tunnel", "/24 to /30, for example 169.254.200.0/24", "The hub and the branches take an address from this network on the tunnel interface; BGP uses these addresses as neighbors. The last address stays free as the hub’s dummy remote-ip."],
  "ms.dialIp": ["Hub IP on the dial-up tunnel", "For example 169.254.200.1", "The BGP neighbor every branch configures."],
  "ms.sites": ["Sites", "", "Name, WAN interface, public address and internal networks of each FortiGate. With the dial-up tunnel on the hub the branches need no public address: they call the hub."],
  "bn.rid": ["Router ID", "For example 10.255.0.1", "An identifier in IP format, unique per FortiGate. If missing the FortiGate picks one and may change it when interfaces change; fixing it keeps sessions and troubleshooting stable.", true],
  "bn.rr": ["Route reflector", "On the hub with many iBGP branches", "In iBGP a router does not pass routes learned from an iBGP neighbor to other iBGP neighbors: every pair would need a session. With a route reflector the hub reflects routes to all branches (route-reflector-client on the neighbors)."],
  "bn.ext": ["External peer", "Provider or non-FortiGate device", "The node is not a FortiGate to configure: Fortissimo makes no tab for it but uses it as the others’ neighbor. For providers, other vendors’ routers or FortiGates managed by someone else."],
  "bn.loName": ["Loopback name", "For example lo_bgp", "An always-up virtual interface BGP starts from (update-source). Up to 15 characters. If it already exists, type its name: Fortissimo creates it in vdom root."],
  "bn.loIp": ["Loopback IP", "For example 10.255.0.1", "The loopback’s /32 address. Needed for loopback sessions: BGP stays up when one link drops, as long as the loopback is reachable over another. Often the same as the router ID.", true],
  "bn.nets": ["Announced networks", "One per line, for example 192.168.10.0/24", "The networks the node announces with config network. The FortiGate announces them only if they are in its routing table. For an IPsec tunnel side, empty uses its local networks.", true],
  "bn.redisConn": ["Redistribute connected networks", "Better with a route-map", "Announces the networks of every FortiGate interface, WAN and management included unless a route-map filters them. Handy with many VLANs."],
  "bn.redisStatic": ["Redistribute static routes", "Better with a route-map", "Announces the FortiGate static routes, the default one included unless filtered. Use it with a route-map that lets through only what is needed."],
  "bn.redisRm": ["Redistribution route-map", "For example RM_REDIST", "Filters what is redistributed. The name must match a route-map defined below.", true],
  "bl.a": ["Side A", "The first node", "One of the two nodes of the session. With dynamic-IP spokes side A is the hub."],
  "bl.b": ["Side B", "The second node", "The other node of the session. With dynamic-IP spokes side B is the spoke."],
  "bl.kind": ["Link", "Tunnel or physical link", "Tunnel: an IPsec or GRE interface, with the neighbor in the tunnel network. Physical link: a direct port or VLAN between the two devices, for example a cable between sites or the provider line."],
  "bl.loop": ["Session over loopbacks", "Off unless there are several links", "The session starts from the loopback instead of the interface: with several links between the same nodes it stays up while one works. Fortissimo generates the loopback, the route to the peer’s one and update-source; in eBGP it adds ebgp-enforce-multihop."],
  "bl.if": ["Interface", "For example VPN_to_B or port3", "The FortiGate interface toward the neighbor: tunnel or port name, exactly as in Network → Interfaces. Up to 15 characters."],
  "bl.ip": ["IP on the link", "For example 169.254.10.1", "This node’s address on the link: the other node uses it as neighbor address. Fortissimo does not set it on the interface, which must already have it; for IPsec tunnels the IPsec part sets it."],
  "bl.dyn": ["Dynamic-IP spokes", "The hub accepts spokes from a network", "The hub does not know the spoke IPs in advance: it accepts BGP from any address of the given network, with neighbor-group and neighbor-range. Side A is the hub."],
  "bl.range": ["Spoke network", "For example 169.254.20.0/24", "The network the hub accepts spoke BGP sessions from. Spoke tunnel IPs must be inside it."],
  "bl.bfd": ["BFD", "To notice failures in under a second", "BFD checks the link far more often than the BGP keepalive: if it drops, the session closes at once and backup routes take over. Fortissimo enables it on the neighbor and on the interface, on both sides."],
  "bl.rmIn": ["Inbound route-map", "For example RM_PRIMARY", "Changes or filters the routes received from this neighbor, for example raising local-preference to prefer this path.", true],
  "bl.rmOut": ["Outbound route-map", "For example RM_BACKUP", "Changes or filters the routes announced to this neighbor, for example with a prepend to make it less preferred on the other side.", true],
  "bl.plIn": ["Inbound prefix-list", "For example PL_ISP_IN", "Accepts from this neighbor only the prefixes the prefix-list permits. Essential toward a provider.", true],
  "bl.plOut": ["Outbound prefix-list", "For example PL_ISP_OUT", "Announces to this neighbor only the permitted prefixes. Toward a provider announce only your public networks.", true],
  "bl.max": ["Maximum-prefix", "For example 10 if the provider sends only the default", "If the neighbor announces more prefixes than this, the session is closed. It protects the routing table from peer mistakes.", true],
  "bl.def": ["Announce the default route", "Usually from the hub to branches", "The FortiGate announces 0.0.0.0/0 to this neighbor (capability-default-originate). Useful from the hub to branches that reach the Internet through head office; toward a provider it is almost always a mistake."],
  "bl.nhs": ["Next-hop-self", "On the hub toward branches", "The FortiGate sets itself as next-hop in the routes it announces to this neighbor. On a route reflector it becomes next-hop-self-rr: branches receive the other branches’ routes with the hub as next-hop, which they can reach."],
  "bp.plName": ["Name", "For example PL_LAN", "Prefix-list name: letters, digits, dot, dash or underscore, up to 35 characters. Sessions refer to it by this name."],
  "bp.plRules": ["Rules", "One per line: permit 10.0.0.0/8 le 24", "Each line is a rule, in order: permit or deny, then a CIDR network or any, then optional ge and le. Without ge and le the network must match exactly: 0.0.0.0/0 is only the default route. 10.0.0.0/8 le 24 = every network inside 10.0.0.0/8 up to /24. An implicit deny follows."],
  "bp.rmName": ["Name", "For example RM_PRIMARY", "Route-map name: letters, digits, dot, dash or underscore, up to 35 characters. Sessions refer to it by this name."],
  "bp.rmRules": ["Rules", "One per line: permit match PL_LAN local-pref 200", "Each line is a rule, in order: permit or deny, then optional match <prefix-list>, local-pref <n>, med <n>, prepend <times, 1–10>, community 65001:100 (several values comma separated) and additive. A rule without match applies to every prefix; prefixes matching no rule are dropped."]
}};
